// Named character constants.  Built with String.fromCharCode so that no exotic
// literal bytes ever appear in the source of the other modules.

export const NUL = String.fromCharCode(0x00);
export const BELL = String.fromCharCode(0x07);
export const BS = String.fromCharCode(0x08);
export const TAB = String.fromCharCode(0x09);
export const LF = String.fromCharCode(0x0a);
export const VT = String.fromCharCode(0x0b);
export const FF = String.fromCharCode(0x0c);
export const CR = String.fromCharCode(0x0d);
export const ESC = String.fromCharCode(0x1b);
export const SPACE = ' ';
export const DEL = String.fromCharCode(0x7f);
export const NEL = String.fromCharCode(0x85);
export const NBSP = String.fromCharCode(0xa0);
export const LS = String.fromCharCode(0x2028);
export const PS = String.fromCharCode(0x2029);
export const BOM = String.fromCharCode(0xfeff);

// '\n\x85  ' -- the characters PyYAML treats as line breaks.
export const LINE_BREAKS = LF + NEL + LS + PS;
// '\0\r\n\x85  '
export const NUL_CR_LINE_BREAKS = NUL + CR + LINE_BREAKS;
// '\r\n\x85  '
export const CR_LINE_BREAKS = CR + LINE_BREAKS;
// '\0 \t\r\n\x85  '
export const NUL_SPACE_TAB_BREAKS = NUL + SPACE + TAB + CR + LINE_BREAKS;
// ' \t' -- inline whitespace
export const SPACE_TAB = SPACE + TAB;

export const DIGITS = '0123456789';
export const HEX_DIGITS = '0123456789abcdefABCDEF';
export const ALPHA = 'abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789-_';

