import { LF, NUL_CR_LINE_BREAKS } from './chars.mjs';

function repeat(ch, n) {
  let out = '';
  for (let i = 0; i < n; i += 1) out += ch;
  return out;
}

export class Mark {
  // `buffer` is an array of code points (see Reader) or null.
  constructor(name, index, line, column, buffer, pointer) {
    this.name = name;
    this.index = index;
    this.line = line;
    this.column = column;
    this.buffer = buffer === undefined ? null : buffer;
    this.pointer = pointer === undefined ? null : pointer;
  }

  getSnippet(indent = 4, maxLength = 75) {
    if (this.buffer === null) return null;
    let head = '';
    let start = this.pointer;
    while (start > 0 && NUL_CR_LINE_BREAKS.indexOf(this.buffer[start - 1]) === -1) {
      start -= 1;
      if (this.pointer - start > maxLength / 2 - 1) {
        head = ' ... ';
        start += 5;
        break;
      }
    }
    let tail = '';
    let end = this.pointer;
    while (end < this.buffer.length && NUL_CR_LINE_BREAKS.indexOf(this.buffer[end]) === -1) {
      end += 1;
      if (end - this.pointer > maxLength / 2 - 1) {
        tail = ' ... ';
        end -= 5;
        break;
      }
