// The Reader: turns the input string into a code-point buffer and tracks
// position, exactly like PyYAML's reader.py does for `str` input.

import { NUL } from './chars.mjs';
import { Mark, ReaderError } from './errors.mjs';

// PyYAML's NON_PRINTABLE character class:
//   [^x09 x0A x0D x20-x7E x85 xA0-D7FF E000-FFFD 10000-10FFFF]
function isPrintableCodePoint(cp) {
  if (cp === 0x09 || cp === 0x0a || cp === 0x0d) return true;
  if (cp >= 0x20 && cp <= 0x7e) return true;
  if (cp === 0x85) return true;
  if (cp >= 0xa0 && cp <= 0xd7ff) return true;
  if (cp >= 0xe000 && cp <= 0xfffd) return true;
  if (cp >= 0x10000 && cp <= 0x10ffff) return true;
  return false;
}

export class Reader {
  constructor(stream) {
    this.name = '<unicode string>';
    this.checkPrintable(stream);
    // A code-point array so that all offsets match Python's string indices.
    this.buffer = Array.from(stream + NUL);
    this.pointer = 0;
    this.index = 0;
    this.line = 0;
    this.column = 0;
  }

  checkPrintable(data) {
    let position = 0;
    for (const ch of data) {
      if (!isPrintableCodePoint(ch.codePointAt(0))) {
        throw new ReaderError(this.name, position, ch.codePointAt(0),
          'unicode', 'special characters are not allowed');
      }
      position += 1;
    }
  }

  peek(index = 0) {
    const i = this.pointer + index;
    if (i >= this.buffer.length) return NUL;
    return this.buffer[i];
  }

  prefix(length = 1) {
    return this.buffer.slice(this.pointer, this.pointer + length).join('');
  }

  forward(length = 1) {
    let n = length;
    while (n) {
      const ch = this.buffer[this.pointer];
      this.pointer += 1;
      this.index += 1;
      const cp = ch === undefined ? -1 : ch.codePointAt(0);
      const isBreak = cp === 0x0a || cp === 0x85 || cp === 0x2028 || cp === 0x2029
        || (cp === 0x0d && this.peek() !== String.fromCharCode(0x0a));
      if (isBreak) {
        this.line += 1;
        this.column = 0;
      } else if (cp !== 0xfeff) {
        this.column += 1;
      }
      n -= 1;
    }
  }

  getMark() {
    return new Mark(this.name, this.index, this.line, this.column,
      this.buffer, this.pointer);
  }
}

