// Token classes -- a direct transcription of PyYAML's tokens.py.

class Token {
  constructor(startMark, endMark) {
    this.startMark = startMark;
    this.endMark = endMark;
  }
}

function defineToken(id) {
  const cls = class extends Token {};
  cls.tid = id;
  return cls;
}

export const DirectiveToken = class extends Token {
  constructor(name, value, startMark, endMark) {
    super(startMark, endMark);
    this.tname = name;
    this.value = value;
  }
};
DirectiveToken.tid = '<directive>';

export const DocumentStartToken = defineToken('<document start>');
export const DocumentEndToken = defineToken('<document end>');

export const StreamStartToken = class extends Token {
  constructor(startMark, endMark, encoding) {
    super(startMark, endMark);
    this.encoding = encoding === undefined ? null : encoding;
  }
};
StreamStartToken.tid = '<stream start>';

export const StreamEndToken = defineToken('<stream end>');
export const BlockSequenceStartToken = defineToken('<block sequence start>');
export const BlockMappingStartToken = defineToken('<block mapping start>');
export const BlockEndToken = defineToken('<block end>');
export const FlowSequenceStartToken = defineToken('[');
export const FlowMappingStartToken = defineToken('{');
export const FlowSequenceEndToken = defineToken(']');
export const FlowMappingEndToken = defineToken('}');
export const KeyToken = defineToken('?');
export const ValueToken = defineToken(':');
export const BlockEntryToken = defineToken('-');
export const FlowEntryToken = defineToken(',');

export const AliasToken = class extends Token {
  constructor(value, startMark, endMark) {
    super(startMark, endMark);
    this.value = value;
  }
};
