// A minimal model of the Python values that safe_load can produce, with the
// hashing, equality and ordering rules CPython uses.

import { PyTypeError, PyValueError } from './errors.mjs';
import { pyFloatRepr } from './pyrepr.mjs';

export const NONE = Object.freeze({ pyNone: true });

export class PyFloat {
  constructor(value) {
    this.value = value;
  }
}

export class PyBytes {
  constructor(bytes) {
    this.bytes = bytes;
  }
}

export class PyTuple {
  constructor(items) {
    this.items = items;
  }
}

function twoDigits(n) {
  return n < 10 ? '0' + n : String(n);
}

function fourDigits(n) {
  let s = String(n);
  while (s.length < 4) s = '0' + s;
  return s;
}

const DAYS_IN_MONTH = [31, 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31];

function isLeap(year) {
  return (year % 4 === 0 && year % 100 !== 0) || year % 400 === 0;
}

export function daysInMonth(year, month) {
  if (month === 2 && isLeap(year)) return 29;
  return DAYS_IN_MONTH[month - 1];
}

function checkDateFields(year, month, day) {
  if (year < 1 || year > 9999) {
    throw new PyValueError('year ' + year + ' is out of range');
  }
  if (month < 1 || month > 12) {
    throw new PyValueError('month must be in 1..12');
  }
  const dim = daysInMonth(year, month);
  if (day < 1 || day > dim) {
    throw new PyValueError('day is out of range for month');
  }
}

function checkTimeFields(hour, minute, second, microsecond) {
  if (hour < 0 || hour > 23) throw new PyValueError('hour must be in 0..23');
  if (minute < 0 || minute > 59) throw new PyValueError('minute must be in 0..59');
  if (second < 0 || second > 59) throw new PyValueError('second must be in 0..59');
  if (microsecond < 0 || microsecond > 999999) {
    throw new PyValueError('microsecond must be in 0..999999');
  }
}

export class PyDate {
  constructor(year, month, day) {
    checkDateFields(year, month, day);
    this.year = year;
    this.month = month;
    this.day = day;
  }

  toOrdinal() {
    let days = 0;
    const y = this.year - 1;
    days += y * 365 + Math.floor(y / 4) - Math.floor(y / 100) + Math.floor(y / 400);
    for (let m = 1; m < this.month; m += 1) days += daysInMonth(this.year, m);
    return days + this.day;
  }

  isoformat() {
    return fourDigits(this.year) + '-' + twoDigits(this.month) + '-' + twoDigits(this.day);
  }
}

export class PyDateTime {
  // tzMinutes: null for a naive datetime, otherwise the utc offset in minutes.
  constructor(year, month, day, hour, minute, second, microsecond, tzMinutes) {
    checkDateFields(year, month, day);
    checkTimeFields(hour, minute, second, microsecond);
    if (tzMinutes !== null && tzMinutes !== undefined
      && (tzMinutes <= -1440 || tzMinutes >= 1440)) {
      throw new PyValueError('offset must be a timedelta strictly between '
        + '-timedelta(hours=24) and timedelta(hours=24).');
    }
