    this.month = month;
    this.day = day;
    this.hour = hour;
    this.minute = minute;
    this.second = second;
    this.microsecond = microsecond;
    this.tzMinutes = tzMinutes === undefined ? null : tzMinutes;
  }

  // Microseconds since the proleptic epoch, ignoring the offset.
  localMicroseconds() {
    const date = new PyDate(this.year, this.month, this.day);
    const days = BigInt(date.toOrdinal());
    return ((days * 86400n + BigInt(this.hour) * 3600n + BigInt(this.minute) * 60n
