  }

  utcMicroseconds() {
    const off = this.tzMinutes === null ? 0 : this.tzMinutes;
    return this.localMicroseconds() - BigInt(off) * 60000000n;
  }

  tzSuffix() {
    if (this.tzMinutes === null) return '';
