  }

  isoformat(sep) {
    let out = fourDigits(this.year) + '-' + twoDigits(this.month) + '-'
      + twoDigits(this.day) + sep + twoDigits(this.hour) + ':'
      + twoDigits(this.minute) + ':' + twoDigits(this.second);
    if (this.microsecond) {
      let frac = String(this.microsecond);
      while (frac.length < 6) frac = '0' + frac;
      out += '.' + frac;
    }
    return out + this.tzSuffix();
  }
