  hasKey(key) {
    return this.index.has(hashKey(key));
  }

  getItem(key) {
    const h = hashKey(key);
    if (!this.index.has(h)) return undefined;
    return this.entries[this.index.get(h)][1];
  }

  update(other) {
    for (const [k, v] of other.entries) this.setItem(k, v);
  }

  get size() {
    return this.entries.length;
  }
