  if (typeof v === 'string') return 's:' + v;
  if (v instanceof PyFloat) {
    const x = v.value;
    if (x !== x) {
      if (!nanIds.has(v)) {
        nanCounter += 1;
        nanIds.set(v, nanCounter);
      }
      return 'nan:' + nanIds.get(v);
    }
    if (x === Infinity) return 'f:inf';
    if (x === -Infinity) return 'f:-inf';
