  return typeof v === 'boolean' || typeof v === 'bigint' || v instanceof PyFloat;
}

function numberValue(v) {
  if (typeof v === 'boolean') return v ? 1 : 0;
  if (typeof v === 'bigint') return Number(v);
  return v.value;
}

