    return out + this.tzSuffix();
  }
}

export class PyDict {
  constructor() {
    this.entries = [];
    this.index = new Map();
  }

  setItem(key, value) {
    const h = hashKey(key);
    if (this.index.has(h)) {
      this.entries[this.index.get(h)][1] = value;
    } else {
      this.index.set(h, this.entries.length);
      this.entries.push([key, value]);
    }
  }

  hasKey(key) {
    return this.index.has(hashKey(key));
  }

  getItem(key) {
    const h = hashKey(key);
    if (!this.index.has(h)) return undefined;
    return this.entries[this.index.get(h)][1];
  }

  update(other) {
    for (const [k, v] of other.entries) this.setItem(k, v);
  }

  get size() {
    return this.entries.length;
  }
}

export class PySet {
  constructor() {
    this.values = [];
    this.index = new Map();
  }

  add(value) {
    const h = hashKey(value);
    if (!this.index.has(h)) {
      this.index.set(h, this.values.length);
      this.values.push(value);
    }
  }
}

export class UnhashableError extends Error {
  constructor(typeName) {
    super("unhashable type: '" + typeName + "'");
    this.typeName = typeName;
  }
}

let nanCounter = 0;
const nanIds = new WeakMap();

export function pyTypeName(v) {
  if (v === NONE) return 'NoneType';
  if (typeof v === 'boolean') return 'bool';
  if (typeof v === 'bigint') return 'int';
  if (typeof v === 'string') return 'str';
  if (v instanceof PyFloat) return 'float';
  if (v instanceof PyBytes) return 'bytes';
  if (Array.isArray(v)) return 'list';
  if (v instanceof PyTuple) return 'tuple';
  if (v instanceof PyDict) return 'dict';
  if (v instanceof PySet) return 'set';
  if (v instanceof PyDateTime) return 'datetime.datetime';
  if (v instanceof PyDate) return 'datetime.date';
  return 'object';
}

export function hashKey(v) {
  if (v === NONE) return 'N';
  if (typeof v === 'boolean') return 'i:' + (v ? '1' : '0');
  if (typeof v === 'bigint') return 'i:' + v.toString();
  if (typeof v === 'string') return 's:' + v;
  if (v instanceof PyFloat) {
    const x = v.value;
    if (x !== x) {
      if (!nanIds.has(v)) {
        nanCounter += 1;
        nanIds.set(v, nanCounter);
      }
      return 'nan:' + nanIds.get(v);
    }
    if (x === Infinity) return 'f:inf';
    if (x === -Infinity) return 'f:-inf';
    if (Number.isInteger(x)) return 'i:' + BigInt(x).toString();
    return 'f:' + pyFloatRepr(x);
  }
  if (v instanceof PyBytes) {
    let s = 'b:';
    for (let i = 0; i < v.bytes.length; i += 1) s += v.bytes[i].toString(16) + '.';
    return s;
  }
  if (v instanceof PyTuple) {
    const parts = [];
    for (const item of v.items) parts.push(hashKey(item));
    return 't(' + parts.join('|') + ')';
  }
  if (v instanceof PyDateTime) {
    if (v.tzMinutes === null) {
      return 'Tn:' + v.localMicroseconds().toString();
    }
    return 'Ta:' + v.utcMicroseconds().toString();
  }
  if (v instanceof PyDate) return 'D:' + v.toOrdinal();
  throw new UnhashableError(pyTypeName(v));
}

function isNumber(v) {
  return typeof v === 'boolean' || typeof v === 'bigint' || v instanceof PyFloat;
}

function numberValue(v) {
  if (typeof v === 'boolean') return v ? 1 : 0;
  if (typeof v === 'bigint') return Number(v);
  return v.value;
}

function compareCodePoints(a, b) {
  const ai = Array.from(a);
  const bi = Array.from(b);
  const n = Math.min(ai.length, bi.length);
  for (let i = 0; i < n; i += 1) {
    const x = ai[i].codePointAt(0);
    const y = bi[i].codePointAt(0);
    if (x !== y) return x < y ? -1 : 1;
  }
  if (ai.length === bi.length) return 0;
  return ai.length < bi.length ? -1 : 1;
}

export function pyEq(a, b) {
  if (a === b) return true;
  if (isNumber(a) && isNumber(b)) {
    if (typeof a === 'bigint' && typeof b === 'bigint') return a === b;
    if (a instanceof PyFloat && a.value !== a.value) return false;
    if (b instanceof PyFloat && b.value !== b.value) return false;
    return numberValue(a) === numberValue(b);
  }
  const ta = pyTypeName(a);
  const tb = pyTypeName(b);
  if (ta !== tb) return false;
  if (ta === 'str') return a === b;
  if (ta === 'bytes') {
    if (a.bytes.length !== b.bytes.length) return false;
    for (let i = 0; i < a.bytes.length; i += 1) {
      if (a.bytes[i] !== b.bytes[i]) return false;
    }
    return true;
  }
  if (ta === 'list' || ta === 'tuple') {
    const ai = ta === 'list' ? a : a.items;
    const bi = ta === 'list' ? b : b.items;
    if (ai.length !== bi.length) return false;
    for (let i = 0; i < ai.length; i += 1) {
      if (!pyEq(ai[i], bi[i])) return false;
    }
    return true;
  }
  if (ta === 'dict') {
    if (a.entries.length !== b.entries.length) return false;
    for (const [k, v] of a.entries) {
      if (!b.hasKey(k)) return false;
      if (!pyEq(b.getItem(k), v)) return false;
    }
    return true;
  }
  if (ta === 'set') {
    if (a.values.length !== b.values.length) return false;
    for (const v of a.values) if (!b.index.has(hashKey(v))) return false;
    return true;
  }
  if (ta === 'datetime.datetime') {
    if ((a.tzMinutes === null) !== (b.tzMinutes === null)) return false;
    return a.utcMicroseconds() === b.utcMicroseconds();
  }
  if (ta === 'datetime.date') return a.toOrdinal() === b.toOrdinal();
  return false;
}

function unorderable(a, b) {
  return new PyTypeError("'<' not supported between instances of '"
    + pyTypeName(a) + "' and '" + pyTypeName(b) + "'");
}

export function pyLess(a, b) {
  if (isNumber(a) && isNumber(b)) {
    if (typeof a === 'bigint' && typeof b === 'bigint') return a < b;
    return numberValue(a) < numberValue(b);
  }
  const ta = pyTypeName(a);
  const tb = pyTypeName(b);
  if (ta === 'str' && tb === 'str') return compareCodePoints(a, b) < 0;
  if (ta === 'bytes' && tb === 'bytes') {
    const n = Math.min(a.bytes.length, b.bytes.length);
    for (let i = 0; i < n; i += 1) {
      if (a.bytes[i] !== b.bytes[i]) return a.bytes[i] < b.bytes[i];
    }
    return a.bytes.length < b.bytes.length;
  }
  if ((ta === 'list' && tb === 'list') || (ta === 'tuple' && tb === 'tuple')) {
    const ai = ta === 'list' ? a : a.items;
    const bi = tb === 'list' ? b : b.items;
    const n = Math.min(ai.length, bi.length);
    for (let i = 0; i < n; i += 1) {
      if (!pyEq(ai[i], bi[i])) return pyLess(ai[i], bi[i]);
    }
    return ai.length < bi.length;
  }
  if (ta === 'set' && tb === 'set') {
    // Python's set.__lt__ is the proper-subset test.
    if (a.values.length >= b.values.length) return false;
    for (const v of a.values) if (!b.index.has(hashKey(v))) return false;
    return true;
  }
  if (ta === 'datetime.datetime' && tb === 'datetime.datetime') {
    if ((a.tzMinutes === null) !== (b.tzMinutes === null)) {
      throw new PyTypeError("can't compare offset-naive and offset-aware datetimes");
    }
    return a.utcMicroseconds() < b.utcMicroseconds();
  }
  if (ta === 'datetime.date' && tb === 'datetime.date') {
    return a.toOrdinal() < b.toOrdinal();
  }
  throw unorderable(a, b);
}

// CPython's list.sort() for short lists: one initial run detection followed by
// a binary insertion sort.  Reproducing the comparison order matters because a
// TypeError raised mid-sort leaves the original list untouched.
export function pySort(items, less) {
  const a = items.slice();
  const n = a.length;
  if (n < 2) return a;
  let runEnd = 2;
  if (less(a[1], a[0])) {
    while (runEnd < n && less(a[runEnd], a[runEnd - 1])) runEnd += 1;
    for (let lo = 0, hi = runEnd - 1; lo < hi; lo += 1, hi -= 1) {
      const t = a[lo];
      a[lo] = a[hi];
      a[hi] = t;
    }
  } else {
    while (runEnd < n && !less(a[runEnd], a[runEnd - 1])) runEnd += 1;
  }
  for (let start = runEnd; start < n; start += 1) {
    const pivot = a[start];
    let l = 0;
    let r = start;
    while (l < r) {
      const p = l + ((r - l) >> 1);
      if (less(pivot, a[p])) r = p; else l = p + 1;
    }
    for (let i = start; i > l; i -= 1) a[i] = a[i - 1];
    a[l] = pivot;
  }
  return a;
}

// sorted() over (key, value) pairs, as PyYAML's represent_mapping does.
export function sortPairs(pairs) {
  const less = (x, y) => {
    if (!pyEq(x[0], y[0])) return pyLess(x[0], y[0]);
    if (!pyEq(x[1], y[1])) return pyLess(x[1], y[1]);
    return false;
  };
  return pySort(pairs, less);
}

export function sortValues(values) {
  return pySort(values, (x, y) => pyLess(x, y));
}

