// The Scanner: produces tokens from the character stream.  A faithful port of
// PyYAML's scanner.py.

import {
  CR, HEX_DIGITS, LF, LINE_BREAKS, NUL, SPACE, TAB,
} from './chars.mjs';
import { ScannerError } from './errors.mjs';
import { pyReprString } from './pyrepr.mjs';
import { Reader } from './reader.mjs';
import {
  AliasToken, AnchorToken, BlockEndToken, BlockEntryToken, BlockMappingStartToken,
  BlockSequenceStartToken, DirectiveToken, DocumentEndToken, DocumentStartToken,
  FlowEntryToken, FlowMappingEndToken, FlowMappingStartToken, FlowSequenceEndToken,
  FlowSequenceStartToken, KeyToken, ScalarToken, StreamEndToken, StreamStartToken,
  TagToken, ValueToken,
} from './tokens.mjs';

// Character classes used throughout the scanner.
const NULL_BL_LINEBR = NUL + CR + LINE_BREAKS;
const NULL_BL_T_LINEBR = NUL + SPACE + TAB + CR + LINE_BREAKS;
const NULL_BL_SP_LINEBR = NUL + SPACE + CR + LINE_BREAKS;
const BL_LINEBR = CR + LINE_BREAKS;
const FULL_LINEBR = CR + LINE_BREAKS;
const SPACES_AND_BREAKS = SPACE + CR + LINE_BREAKS;

const ANCHOR_STOP = NUL + SPACE + TAB + CR + LINE_BREAKS + '?:,]}%@`';
const PLAIN_FORBIDDEN_FIRST = NUL + SPACE + TAB + CR + LINE_BREAKS
  + '-?:,[]{}#&*!|>' + "'" + '"' + '%@`';
const FLOW_SCALAR_STOP = "'" + '"' + '\\' + NUL + SPACE + TAB + CR + LINE_BREAKS;
const TAG_URI_EXTRA = "-;/?:@&=+$,_.!~*'()[]%";

const ESCAPE_REPLACEMENTS = new Map([
  ['0', String.fromCharCode(0x00)],
  ['a', String.fromCharCode(0x07)],
  ['b', String.fromCharCode(0x08)],
  ['t', String.fromCharCode(0x09)],
  [TAB, String.fromCharCode(0x09)],
  ['n', String.fromCharCode(0x0a)],
  ['v', String.fromCharCode(0x0b)],
  ['f', String.fromCharCode(0x0c)],
  ['r', String.fromCharCode(0x0d)],
  ['e', String.fromCharCode(0x1b)],
  [' ', String.fromCharCode(0x20)],
  ['"', '"'],
  ['\\', '\\'],
  ['/', '/'],
  ['N', String.fromCharCode(0x85)],
  ['_', String.fromCharCode(0xa0)],
  ['L', String.fromCharCode(0x2028)],
  ['P', String.fromCharCode(0x2029)],
]);

const ESCAPE_CODES = new Map([['x', 2], ['u', 4], ['U', 8]]);

function isIn(ch, set) {
  return set.indexOf(ch) !== -1;
}

function isAlnumDash(ch) {
  return (ch >= '0' && ch <= '9') || (ch >= 'A' && ch <= 'Z')
    || (ch >= 'a' && ch <= 'z') || ch === '-' || ch === '_';
}

class SimpleKey {
  constructor(tokenNumber, required, index, line, column, mark) {
    this.tokenNumber = tokenNumber;
    this.required = required;
    this.index = index;
    this.line = line;
    this.column = column;
    this.mark = mark;
  }
}

export class Scanner extends Reader {
  constructor(stream) {
    super(stream);
    this.done = false;
    this.flowLevel = 0;
    this.tokens = [];
    this.fetchStreamStart();
    this.tokensTaken = 0;
    this.indent = -1;
    this.indents = [];
    this.allowSimpleKey = true;
    this.possibleSimpleKeys = new Map();
  }

  // -- public token interface -------------------------------------------------

  checkToken(...choices) {
    while (this.needMoreTokens()) this.fetchMoreTokens();
    if (this.tokens.length) {
      if (!choices.length) return true;
      for (const choice of choices) {
        if (this.tokens[0] instanceof choice) return true;
      }
    }
    return false;
  }

  peekToken() {
    while (this.needMoreTokens()) this.fetchMoreTokens();
    if (this.tokens.length) return this.tokens[0];
    return null;
  }

  getToken() {
    while (this.needMoreTokens()) this.fetchMoreTokens();
    if (this.tokens.length) {
      this.tokensTaken += 1;
      return this.tokens.shift();
    }
    return null;
  }

  needMoreTokens() {
    if (this.done) return false;
    if (!this.tokens.length) return true;
    this.stalePossibleSimpleKeys();
    if (this.nextPossibleSimpleKey() === this.tokensTaken) return true;
    return false;
  }

  fetchMoreTokens() {
    this.scanToNextToken();
    this.stalePossibleSimpleKeys();
    this.unwindIndent(this.column);
    const ch = this.peek();
    if (ch === NUL) return this.fetchStreamEnd();
    if (ch === '%' && this.checkDirective()) return this.fetchDirective();
    if (ch === '-' && this.checkDocumentStart()) return this.fetchDocumentStart();
    if (ch === '.' && this.checkDocumentEnd()) return this.fetchDocumentEnd();
    if (ch === '[') return this.fetchFlowSequenceStart();
    if (ch === '{') return this.fetchFlowMappingStart();
    if (ch === ']') return this.fetchFlowSequenceEnd();
    if (ch === '}') return this.fetchFlowMappingEnd();
    if (ch === ',') return this.fetchFlowEntry();
    if (ch === '-' && this.checkBlockEntry()) return this.fetchBlockEntry();
    if (ch === '?' && this.checkKey()) return this.fetchKey();
    if (ch === ':' && this.checkValue()) return this.fetchValue();
    if (ch === '*') return this.fetchAlias();
    if (ch === '&') return this.fetchAnchor();
    if (ch === '!') return this.fetchTag();
    if (ch === '|' && !this.flowLevel) return this.fetchLiteral();
    if (ch === '>' && !this.flowLevel) return this.fetchFolded();
    if (ch === "'") return this.fetchSingle();
    if (ch === '"') return this.fetchDouble();
    if (this.checkPlain()) return this.fetchPlain();
    throw new ScannerError('while scanning for the next token', null,
      'found character ' + pyReprString(ch) + ' that cannot start any token',
      this.getMark());
  }

  // -- simple keys -----------------------------------------------------------

  nextPossibleSimpleKey() {
    let minTokenNumber = null;
    for (const key of this.possibleSimpleKeys.values()) {
      if (minTokenNumber === null || key.tokenNumber < minTokenNumber) {
        minTokenNumber = key.tokenNumber;
      }
    }
    return minTokenNumber;
  }

  stalePossibleSimpleKeys() {
    for (const level of Array.from(this.possibleSimpleKeys.keys())) {
      const key = this.possibleSimpleKeys.get(level);
      if (key.line !== this.line || this.index - key.index > 1024) {
        if (key.required) {
          throw new ScannerError('while scanning a simple key', key.mark,
            "could not find expected ':'", this.getMark());
        }
        this.possibleSimpleKeys.delete(level);
      }
    }
  }

  savePossibleSimpleKey() {
    const required = !this.flowLevel && this.indent === this.column;
    if (this.allowSimpleKey) {
      this.removePossibleSimpleKey();
      const tokenNumber = this.tokensTaken + this.tokens.length;
      const key = new SimpleKey(tokenNumber, required, this.index, this.line,
        this.column, this.getMark());
      this.possibleSimpleKeys.set(this.flowLevel, key);
    }
  }

  removePossibleSimpleKey() {
    if (this.possibleSimpleKeys.has(this.flowLevel)) {
      const key = this.possibleSimpleKeys.get(this.flowLevel);
      if (key.required) {
        throw new ScannerError('while scanning a simple key', key.mark,
          "could not find expected ':'", this.getMark());
      }
      this.possibleSimpleKeys.delete(this.flowLevel);
    }
  }

  // -- indentation -----------------------------------------------------------

  unwindIndent(column) {
    if (this.flowLevel) return;
    while (this.indent > column) {
      const mark = this.getMark();
      this.indent = this.indents.pop();
      this.tokens.push(new BlockEndToken(mark, mark));
    }
  }

  addIndent(column) {
    if (this.indent < column) {
      this.indents.push(this.indent);
      this.indent = column;
      return true;
    }
    return false;
  }

  // -- fetchers --------------------------------------------------------------

  fetchStreamStart() {
    const mark = this.getMark();
    this.tokens.push(new StreamStartToken(mark, mark, null));
  }

  fetchStreamEnd() {
    this.unwindIndent(-1);
    this.removePossibleSimpleKey();
    this.allowSimpleKey = false;
    this.possibleSimpleKeys = new Map();
    const mark = this.getMark();
    this.tokens.push(new StreamEndToken(mark, mark));
    this.done = true;
    return undefined;
  }

  fetchDirective() {
    this.unwindIndent(-1);
    this.removePossibleSimpleKey();
    this.allowSimpleKey = false;
    this.tokens.push(this.scanDirective());
    return undefined;
  }

  fetchDocumentStart() {
    return this.fetchDocumentIndicator(DocumentStartToken);
  }

  fetchDocumentEnd() {
    return this.fetchDocumentIndicator(DocumentEndToken);
  }

  fetchDocumentIndicator(TokenClass) {
    this.unwindIndent(-1);
    this.removePossibleSimpleKey();
    this.allowSimpleKey = false;
    const startMark = this.getMark();
    this.forward(3);
    const endMark = this.getMark();
    this.tokens.push(new TokenClass(startMark, endMark));
    return undefined;
  }

  fetchFlowSequenceStart() {
    return this.fetchFlowCollectionStart(FlowSequenceStartToken);
  }

  fetchFlowMappingStart() {
    return this.fetchFlowCollectionStart(FlowMappingStartToken);
  }

  fetchFlowCollectionStart(TokenClass) {
    this.savePossibleSimpleKey();
    this.flowLevel += 1;
    this.allowSimpleKey = true;
    const startMark = this.getMark();
    this.forward();
    const endMark = this.getMark();
    this.tokens.push(new TokenClass(startMark, endMark));
    return undefined;
  }

  fetchFlowSequenceEnd() {
    return this.fetchFlowCollectionEnd(FlowSequenceEndToken);
  }

  fetchFlowMappingEnd() {
    return this.fetchFlowCollectionEnd(FlowMappingEndToken);
  }

  fetchFlowCollectionEnd(TokenClass) {
    this.removePossibleSimpleKey();
    this.flowLevel -= 1;
    this.allowSimpleKey = false;
    const startMark = this.getMark();
    this.forward();
    const endMark = this.getMark();
    this.tokens.push(new TokenClass(startMark, endMark));
    return undefined;
  }

  fetchFlowEntry() {
    this.allowSimpleKey = true;
    this.removePossibleSimpleKey();
    const startMark = this.getMark();
    this.forward();
    const endMark = this.getMark();
    this.tokens.push(new FlowEntryToken(startMark, endMark));
    return undefined;
  }

  fetchBlockEntry() {
    if (!this.flowLevel) {
      if (!this.allowSimpleKey) {
        throw new ScannerError(null, null,
          'sequence entries are not allowed here', this.getMark());
      }
      if (this.addIndent(this.column)) {
        const mark = this.getMark();
        this.tokens.push(new BlockSequenceStartToken(mark, mark));
      }
    }
    this.allowSimpleKey = true;
    this.removePossibleSimpleKey();
    const startMark = this.getMark();
    this.forward();
    const endMark = this.getMark();
    this.tokens.push(new BlockEntryToken(startMark, endMark));
    return undefined;
  }

  fetchKey() {
    if (!this.flowLevel) {
      if (!this.allowSimpleKey) {
        throw new ScannerError(null, null,
          'mapping keys are not allowed here', this.getMark());
      }
      if (this.addIndent(this.column)) {
        const mark = this.getMark();
        this.tokens.push(new BlockMappingStartToken(mark, mark));
      }
    }
    this.allowSimpleKey = !this.flowLevel;
    this.removePossibleSimpleKey();
    const startMark = this.getMark();
    this.forward();
    const endMark = this.getMark();
    this.tokens.push(new KeyToken(startMark, endMark));
    return undefined;
  }

  fetchValue() {
    if (this.possibleSimpleKeys.has(this.flowLevel)) {
      const key = this.possibleSimpleKeys.get(this.flowLevel);
      this.possibleSimpleKeys.delete(this.flowLevel);
      this.tokens.splice(key.tokenNumber - this.tokensTaken, 0,
        new KeyToken(key.mark, key.mark));
      if (!this.flowLevel) {
        if (this.addIndent(key.column)) {
          this.tokens.splice(key.tokenNumber - this.tokensTaken, 0,
            new BlockMappingStartToken(key.mark, key.mark));
        }
      }
      this.allowSimpleKey = false;
    } else {
      if (!this.flowLevel) {
        if (!this.allowSimpleKey) {
          throw new ScannerError(null, null,
            'mapping values are not allowed here', this.getMark());
        }
      }
      if (!this.flowLevel) {
        if (this.addIndent(this.column)) {
          const mark = this.getMark();
          this.tokens.push(new BlockMappingStartToken(mark, mark));
        }
      }
      this.allowSimpleKey = !this.flowLevel;
      this.removePossibleSimpleKey();
    }
    const startMark = this.getMark();
    this.forward();
    const endMark = this.getMark();
    this.tokens.push(new ValueToken(startMark, endMark));
    return undefined;
  }

  fetchAlias() {
    this.savePossibleSimpleKey();
    this.allowSimpleKey = false;
    this.tokens.push(this.scanAnchor(AliasToken));
    return undefined;
  }

  fetchAnchor() {
    this.savePossibleSimpleKey();
    this.allowSimpleKey = false;
    this.tokens.push(this.scanAnchor(AnchorToken));
    return undefined;
  }

  fetchTag() {
    this.savePossibleSimpleKey();
    this.allowSimpleKey = false;
    this.tokens.push(this.scanTag());
    return undefined;
  }

  fetchLiteral() {
    return this.fetchBlockScalar('|');
  }

  fetchFolded() {
    return this.fetchBlockScalar('>');
  }

  fetchBlockScalar(style) {
    this.allowSimpleKey = true;
    this.removePossibleSimpleKey();
    this.tokens.push(this.scanBlockScalar(style));
    return undefined;
  }

  fetchSingle() {
    return this.fetchFlowScalar("'");
  }

  fetchDouble() {
    return this.fetchFlowScalar('"');
  }

  fetchFlowScalar(style) {
    this.savePossibleSimpleKey();
    this.allowSimpleKey = false;
    this.tokens.push(this.scanFlowScalar(style));
    return undefined;
  }

  fetchPlain() {
    this.savePossibleSimpleKey();
    this.allowSimpleKey = false;
    this.tokens.push(this.scanPlain());
    return undefined;
  }

  // -- checkers --------------------------------------------------------------

  checkDirective() {
    return this.column === 0;
  }

  checkDocumentStart() {
    if (this.column === 0) {
      if (this.prefix(3) === '---' && isIn(this.peek(3), NULL_BL_T_LINEBR)) return true;
    }
    return false;
  }

  checkDocumentEnd() {
    if (this.column === 0) {
      if (this.prefix(3) === '...' && isIn(this.peek(3), NULL_BL_T_LINEBR)) return true;
    }
    return false;
  }

  checkBlockEntry() {
    return isIn(this.peek(1), NULL_BL_T_LINEBR);
  }

  checkKey() {
    if (this.flowLevel) return true;
    return isIn(this.peek(1), NULL_BL_T_LINEBR);
  }

  checkValue() {
    if (this.flowLevel) return true;
    return isIn(this.peek(1), NULL_BL_T_LINEBR);
  }

  checkPlain() {
    const ch = this.peek();
    return !isIn(ch, PLAIN_FORBIDDEN_FIRST)
      || (!isIn(this.peek(1), NULL_BL_T_LINEBR)
        && (ch === '-' || (!this.flowLevel && (ch === '?' || ch === ':'))));
  }

  // -- scanners --------------------------------------------------------------

  scanToNextToken() {
    if (this.index === 0 && this.peek() === String.fromCharCode(0xfeff)) {
      this.forward();
    }
    let found = false;
    while (!found) {
      while (this.peek() === SPACE) this.forward();
      if (this.peek() === '#') {
        while (!isIn(this.peek(), NULL_BL_LINEBR)) this.forward();
      }
      if (this.scanLineBreak()) {
        if (!this.flowLevel) this.allowSimpleKey = true;
      } else {
        found = true;
      }
    }
  }

  scanDirective() {
    const startMark = this.getMark();
    this.forward();
    const name = this.scanDirectiveName(startMark);
    let value = null;
    let endMark;
    if (name === 'YAML') {
      value = this.scanYamlDirectiveValue(startMark);
      endMark = this.getMark();
    } else if (name === 'TAG') {
      value = this.scanTagDirectiveValue(startMark);
      endMark = this.getMark();
    } else {
      endMark = this.getMark();
      while (!isIn(this.peek(), NULL_BL_LINEBR)) this.forward();
    }
    this.scanDirectiveIgnoredLine(startMark);
    return new DirectiveToken(name, value, startMark, endMark);
  }

  scanDirectiveName(startMark) {
    let length = 0;
    let ch = this.peek(length);
    while (isAlnumDash(ch)) {
      length += 1;
      ch = this.peek(length);
    }
    if (!length) {
      throw new ScannerError('while scanning a directive', startMark,
        'expected alphabetic or numeric character, but found ' + pyReprString(ch),
        this.getMark());
    }
    const value = this.prefix(length);
    this.forward(length);
    ch = this.peek();
    if (!isIn(ch, NULL_BL_SP_LINEBR)) {
      throw new ScannerError('while scanning a directive', startMark,
        'expected alphabetic or numeric character, but found ' + pyReprString(ch),
        this.getMark());
    }
    return value;
  }

  scanYamlDirectiveValue(startMark) {
    while (this.peek() === SPACE) this.forward();
    const major = this.scanYamlDirectiveNumber(startMark);
    if (this.peek() !== '.') {
      throw new ScannerError('while scanning a directive', startMark,
        "expected a digit or '.', but found " + pyReprString(this.peek()),
        this.getMark());
    }
    this.forward();
    const minor = this.scanYamlDirectiveNumber(startMark);
    if (!isIn(this.peek(), NULL_BL_SP_LINEBR)) {
      throw new ScannerError('while scanning a directive', startMark,
        "expected a digit or ' ', but found " + pyReprString(this.peek()),
        this.getMark());
    }
    return [major, minor];
  }

  scanYamlDirectiveNumber(startMark) {
    const ch = this.peek();
    if (!(ch >= '0' && ch <= '9')) {
      throw new ScannerError('while scanning a directive', startMark,
        'expected a digit, but found ' + pyReprString(ch), this.getMark());
    }
    let length = 0;
    while (this.peek(length) >= '0' && this.peek(length) <= '9') length += 1;
    const value = Number(this.prefix(length));
    this.forward(length);
    return value;
  }

  scanTagDirectiveValue(startMark) {
    while (this.peek() === SPACE) this.forward();
    const handle = this.scanTagDirectiveHandle(startMark);
    while (this.peek() === SPACE) this.forward();
    const prefix = this.scanTagDirectivePrefix(startMark);
    return [handle, prefix];
  }

  scanTagDirectiveHandle(startMark) {
    const value = this.scanTagHandle('directive', startMark);
    const ch = this.peek();
    if (ch !== SPACE) {
      throw new ScannerError('while scanning a directive', startMark,
        "expected ' ', but found " + pyReprString(ch), this.getMark());
    }
    return value;
  }

  scanTagDirectivePrefix(startMark) {
    const value = this.scanTagUri('directive', startMark);
    const ch = this.peek();
    if (!isIn(ch, NULL_BL_SP_LINEBR)) {
      throw new ScannerError('while scanning a directive', startMark,
        "expected ' ', but found " + pyReprString(ch), this.getMark());
    }
    return value;
  }

  scanDirectiveIgnoredLine(startMark) {
    while (this.peek() === SPACE) this.forward();
    if (this.peek() === '#') {
      while (!isIn(this.peek(), NULL_BL_LINEBR)) this.forward();
    }
    const ch = this.peek();
    if (!isIn(ch, NULL_BL_LINEBR)) {
      throw new ScannerError('while scanning a directive', startMark,
        'expected a comment or a line break, but found ' + pyReprString(ch),
        this.getMark());
    }
    this.scanLineBreak();
  }

  scanAnchor(TokenClass) {
    const startMark = this.getMark();
    const indicator = this.peek();
    const name = indicator === '*' ? 'alias' : 'anchor';
    this.forward();
    let length = 0;
    let ch = this.peek(length);
    while (isAlnumDash(ch)) {
      length += 1;
      ch = this.peek(length);
    }
    if (!length) {
      throw new ScannerError('while scanning an ' + name, startMark,
        'expected alphabetic or numeric character, but found ' + pyReprString(ch),
        this.getMark());
    }
    const value = this.prefix(length);
    this.forward(length);
    ch = this.peek();
    if (!isIn(ch, ANCHOR_STOP)) {
      throw new ScannerError('while scanning an ' + name, startMark,
        'expected alphabetic or numeric character, but found ' + pyReprString(ch),
        this.getMark());
    }
    const endMark = this.getMark();
    return new TokenClass(value, startMark, endMark);
  }

  scanTag() {
    const startMark = this.getMark();
    let ch = this.peek(1);
    let handle;
    let suffix;
    if (ch === '<') {
      handle = null;
      this.forward(2);
      suffix = this.scanTagUri('tag', startMark);
      if (this.peek() !== '>') {
        throw new ScannerError('while parsing a tag', startMark,
          "expected '>', but found " + pyReprString(this.peek()), this.getMark());
      }
      this.forward();
    } else if (isIn(ch, NULL_BL_T_LINEBR)) {
      handle = null;
      suffix = '!';
      this.forward();
    } else {
      let length = 1;
      let useHandle = false;
      while (!isIn(ch, NULL_BL_SP_LINEBR)) {
        if (ch === '!') {
          useHandle = true;
          break;
        }
        length += 1;
        ch = this.peek(length);
      }
      if (useHandle) {
        handle = this.scanTagHandle('tag', startMark);
      } else {
        handle = '!';
        this.forward();
      }
      suffix = this.scanTagUri('tag', startMark);
    }
    ch = this.peek();
    if (!isIn(ch, NULL_BL_SP_LINEBR)) {
      throw new ScannerError('while scanning a tag', startMark,
        "expected ' ', but found " + pyReprString(ch), this.getMark());
    }
    const endMark = this.getMark();
    return new TagToken([handle, suffix], startMark, endMark);
  }

  scanBlockScalar(style) {
    const folded = style === '>';
    const chunks = [];
    const startMark = this.getMark();
    this.forward();
    const [chomping, increment] = this.scanBlockScalarIndicators(startMark);
    this.scanBlockScalarIgnoredLine(startMark);
    let minIndent = this.indent + 1;
    if (minIndent < 1) minIndent = 1;
    let breaks;
    let indent;
    let endMark;
    if (increment === null) {
      const res = this.scanBlockScalarIndentation();
      breaks = res[0];
      const maxIndent = res[1];
      endMark = res[2];
      indent = Math.max(minIndent, maxIndent);
    } else {
      indent = minIndent + increment - 1;
      const res = this.scanBlockScalarBreaks(indent);
      breaks = res[0];
      endMark = res[1];
    }
    let lineBreak = '';
    while (this.column === indent && this.peek() !== NUL) {
      for (const b of breaks) chunks.push(b);
      const leadingNonSpace = this.peek() !== SPACE && this.peek() !== TAB;
      let length = 0;
      while (!isIn(this.peek(length), NULL_BL_LINEBR)) length += 1;
      chunks.push(this.prefix(length));
      this.forward(length);
      lineBreak = this.scanLineBreak();
      const res = this.scanBlockScalarBreaks(indent);
      breaks = res[0];
      endMark = res[1];
      if (this.column === indent && this.peek() !== NUL) {
        if (folded && lineBreak === LF && leadingNonSpace
          && this.peek() !== SPACE && this.peek() !== TAB) {
          if (!breaks.length) chunks.push(SPACE);
        } else {
          chunks.push(lineBreak);
        }
      } else {
        break;
      }
    }
    if (chomping !== false) chunks.push(lineBreak);
    if (chomping === true) for (const b of breaks) chunks.push(b);
    return new ScalarToken(chunks.join(''), false, startMark, endMark, style);
  }

  scanBlockScalarIndicators(startMark) {
    let chomping = null;
    let increment = null;
    let ch = this.peek();
    if (ch === '+' || ch === '-') {
      chomping = ch === '+';
      this.forward();
      ch = this.peek();
      if (ch >= '0' && ch <= '9') {
        increment = Number(ch);
        if (increment === 0) {
          throw new ScannerError('while scanning a block scalar', startMark,
            'expected indentation indicator in the range 1-9, but found 0',
            this.getMark());
        }
        this.forward();
      }
    } else if (ch >= '0' && ch <= '9') {
      increment = Number(ch);
      if (increment === 0) {
        throw new ScannerError('while scanning a block scalar', startMark,
          'expected indentation indicator in the range 1-9, but found 0',
          this.getMark());
      }
      this.forward();
      ch = this.peek();
      if (ch === '+' || ch === '-') {
        chomping = ch === '+';
        this.forward();
      }
    }
    ch = this.peek();
    if (!isIn(ch, NULL_BL_SP_LINEBR)) {
      throw new ScannerError('while scanning a block scalar', startMark,
        'expected chomping or indentation indicators, but found ' + pyReprString(ch),
        this.getMark());
    }
    return [chomping, increment];
  }

  scanBlockScalarIgnoredLine(startMark) {
    while (this.peek() === SPACE) this.forward();
    if (this.peek() === '#') {
      while (!isIn(this.peek(), NULL_BL_LINEBR)) this.forward();
    }
    const ch = this.peek();
    if (!isIn(ch, NULL_BL_LINEBR)) {
      throw new ScannerError('while scanning a block scalar', startMark,
        'expected a comment or a line break, but found ' + pyReprString(ch),
        this.getMark());
    }
    this.scanLineBreak();
  }

  scanBlockScalarIndentation() {
    const chunks = [];
    let maxIndent = 0;
    let endMark = this.getMark();
    while (isIn(this.peek(), SPACES_AND_BREAKS)) {
      if (this.peek() !== SPACE) {
        chunks.push(this.scanLineBreak());
        endMark = this.getMark();
      } else {
        this.forward();
        if (this.column > maxIndent) maxIndent = this.column;
      }
    }
    return [chunks, maxIndent, endMark];
  }

  scanBlockScalarBreaks(indent) {
    const chunks = [];
    let endMark = this.getMark();
    while (this.column < indent && this.peek() === SPACE) this.forward();
    while (isIn(this.peek(), FULL_LINEBR)) {
      chunks.push(this.scanLineBreak());
      endMark = this.getMark();
      while (this.column < indent && this.peek() === SPACE) this.forward();
    }
    return [chunks, endMark];
  }

  scanFlowScalar(style) {
    const double = style === '"';
    const chunks = [];
    const startMark = this.getMark();
    const quote = this.peek();
    this.forward();
    for (const c of this.scanFlowScalarNonSpaces(double, startMark)) chunks.push(c);
    while (this.peek() !== quote) {
      for (const c of this.scanFlowScalarSpaces(double, startMark)) chunks.push(c);
      for (const c of this.scanFlowScalarNonSpaces(double, startMark)) chunks.push(c);
    }
    this.forward();
    const endMark = this.getMark();
    return new ScalarToken(chunks.join(''), false, startMark, endMark, style);
  }

  scanFlowScalarNonSpaces(double, startMark) {
    const chunks = [];
    for (;;) {
      let length = 0;
      while (!isIn(this.peek(length), FLOW_SCALAR_STOP)) length += 1;
      if (length) {
        chunks.push(this.prefix(length));
        this.forward(length);
      }
      let ch = this.peek();
      if (!double && ch === "'" && this.peek(1) === "'") {
        chunks.push("'");
        this.forward(2);
      } else if ((double && ch === "'") || (!double && (ch === '"' || ch === '\\'))) {
        chunks.push(ch);
        this.forward();
      } else if (double && ch === '\\') {
        this.forward();
        ch = this.peek();
        if (ESCAPE_REPLACEMENTS.has(ch)) {
          chunks.push(ESCAPE_REPLACEMENTS.get(ch));
          this.forward();
        } else if (ESCAPE_CODES.has(ch)) {
          const length2 = ESCAPE_CODES.get(ch);
          this.forward();
          for (let k = 0; k < length2; k += 1) {
            if (!isIn(this.peek(k), HEX_DIGITS)) {
              throw new ScannerError('while scanning a double-quoted scalar', startMark,
                'expected escape sequence of ' + length2 + ' hexdecimal numbers, but found '
                + pyReprString(this.peek(k)), this.getMark());
            }
          }
          const code = parseInt(this.prefix(length2), 16);
          chunks.push(String.fromCodePoint(code));
          this.forward(length2);
        } else if (isIn(ch, FULL_LINEBR)) {
          this.scanLineBreak();
          for (const c of this.scanFlowScalarBreaks(double, startMark)) chunks.push(c);
        } else {
          throw new ScannerError('while scanning a double-quoted scalar', startMark,
            'found unknown escape character ' + pyReprString(ch), this.getMark());
        }
      } else {
        return chunks;
      }
    }
  }

  scanFlowScalarSpaces(double, startMark) {
    const chunks = [];
    let length = 0;
    while (this.peek(length) === SPACE || this.peek(length) === TAB) length += 1;
    const whitespaces = this.prefix(length);
    this.forward(length);
    const ch = this.peek();
    if (ch === NUL) {
      throw new ScannerError('while scanning a quoted scalar', startMark,
        'found unexpected end of stream', this.getMark());
    } else if (isIn(ch, FULL_LINEBR)) {
      const lineBreak = this.scanLineBreak();
      const breaks = this.scanFlowScalarBreaks(double, startMark);
      if (lineBreak !== LF) {
        chunks.push(lineBreak);
      } else if (!breaks.length) {
        chunks.push(SPACE);
      }
      for (const b of breaks) chunks.push(b);
    } else {
      chunks.push(whitespaces);
    }
    return chunks;
  }

  scanFlowScalarBreaks(double, startMark) {
    const chunks = [];
    for (;;) {
      const prefix = this.prefix(3);
      if ((prefix === '---' || prefix === '...') && isIn(this.peek(3), NULL_BL_T_LINEBR)) {
        throw new ScannerError('while scanning a quoted scalar', startMark,
          'found unexpected document separator', this.getMark());
      }
      while (this.peek() === SPACE || this.peek() === TAB) this.forward();
      if (isIn(this.peek(), FULL_LINEBR)) {
        chunks.push(this.scanLineBreak());
      } else {
        return chunks;
      }
    }
  }

  scanPlain() {
    const chunks = [];
    const startMark = this.getMark();
    let endMark = startMark;
    const indent = this.indent + 1;
    let spaces = [];
    for (;;) {
      let length = 0;
      if (this.peek() === '#') break;
      for (;;) {
        const ch = this.peek(length);
        const stopAfterColon = NULL_BL_T_LINEBR + (this.flowLevel ? ',[]{}' : '');
        if (isIn(ch, NULL_BL_T_LINEBR)
          || (ch === ':' && isIn(this.peek(length + 1), stopAfterColon))
          || (this.flowLevel && isIn(ch, ',?[]{}'))) {
          break;
        }
        length += 1;
      }
      if (length === 0) break;
      this.allowSimpleKey = false;
      for (const s of spaces) chunks.push(s);
      chunks.push(this.prefix(length));
      this.forward(length);
      endMark = this.getMark();
      spaces = this.scanPlainSpaces(indent, startMark);
      if (spaces === null || spaces.length === 0 || this.peek() === '#'
        || (!this.flowLevel && this.column < indent)) {
        break;
      }
    }
    return new ScalarToken(chunks.join(''), true, startMark, endMark, null);
  }

  scanPlainSpaces(indent, startMark) {
    const chunks = [];
    let length = 0;
    while (this.peek(length) === SPACE) length += 1;
    const whitespaces = this.prefix(length);
    this.forward(length);
    const ch = this.peek();
    if (isIn(ch, FULL_LINEBR)) {
      const lineBreak = this.scanLineBreak();
      this.allowSimpleKey = true;
      let prefix = this.prefix(3);
      if ((prefix === '---' || prefix === '...') && isIn(this.peek(3), NULL_BL_T_LINEBR)) {
        return null;
      }
      const breaks = [];
      while (isIn(this.peek(), SPACES_AND_BREAKS)) {
        if (this.peek() === SPACE) {
          this.forward();
        } else {
          breaks.push(this.scanLineBreak());
          prefix = this.prefix(3);
          if ((prefix === '---' || prefix === '...') && isIn(this.peek(3), NULL_BL_T_LINEBR)) {
            return null;
          }
        }
      }
      if (lineBreak !== LF) {
        chunks.push(lineBreak);
      } else if (!breaks.length) {
        chunks.push(SPACE);
      }
      for (const b of breaks) chunks.push(b);
    } else if (whitespaces) {
      chunks.push(whitespaces);
    }
    return chunks;
  }

  scanTagHandle(name, startMark) {
    let ch = this.peek();
    if (ch !== '!') {
      throw new ScannerError('while scanning a ' + name, startMark,
        "expected '!', but found " + pyReprString(ch), this.getMark());
    }
    let length = 1;
    ch = this.peek(length);
    if (ch !== SPACE) {
      while (isAlnumDash(ch)) {
        length += 1;
        ch = this.peek(length);
      }
      if (ch !== '!') {
        this.forward(length);
        throw new ScannerError('while scanning a ' + name, startMark,
          "expected '!', but found " + pyReprString(ch), this.getMark());
      }
      length += 1;
    }
    const value = this.prefix(length);
    this.forward(length);
    return value;
  }

  scanTagUri(name, startMark) {
    const chunks = [];
    let length = 0;
    let ch = this.peek(length);
    while ((ch >= '0' && ch <= '9') || (ch >= 'A' && ch <= 'Z')
      || (ch >= 'a' && ch <= 'z') || isIn(ch, TAG_URI_EXTRA)) {
      if (ch === '%') {
        chunks.push(this.prefix(length));
        this.forward(length);
        length = 0;
        chunks.push(this.scanUriEscapes(name, startMark));
      } else {
        length += 1;
      }
      ch = this.peek(length);
    }
    if (length) {
      chunks.push(this.prefix(length));
      this.forward(length);
      length = 0;
    }
    if (!chunks.length) {
      throw new ScannerError('while parsing a ' + name, startMark,
        'expected URI, but found ' + pyReprString(ch), this.getMark());
    }
    return chunks.join('');
  }

  scanUriEscapes(name, startMark) {
    const codes = [];
    const mark = this.getMark();
    while (this.peek() === '%') {
      this.forward();
      for (let k = 0; k < 2; k += 1) {
        if (!isIn(this.peek(k), HEX_DIGITS)) {
          throw new ScannerError('while scanning a ' + name, startMark,
            'expected URI escape sequence of 2 hexdecimal numbers, but found '
            + pyReprString(this.peek(k)), this.getMark());
        }
      }
      codes.push(parseInt(this.prefix(2), 16));
      this.forward(2);
    }
    // Decode the collected bytes as UTF-8.
    const { utf8Decode, UnicodeDecodeError } = this.constructor.utf8Helpers;
    try {
      return utf8Decode(Uint8Array.from(codes));
    } catch (exc) {
      if (exc instanceof UnicodeDecodeError) {
        throw new ScannerError('while scanning a ' + name, startMark, exc.message, mark);
      }
      throw exc;
    }
  }

  scanLineBreak() {
    const ch = this.peek();
    if (ch === CR || ch === LF || ch === String.fromCharCode(0x85)) {
      if (this.prefix(2) === CR + LF) {
        this.forward(2);
      } else {
        this.forward();
      }
      return LF;
    }
    if (ch === String.fromCharCode(0x2028) || ch === String.fromCharCode(0x2029)) {
      this.forward();
      return ch;
    }
    return '';
  }
}

export { BL_LINEBR, NULL_BL_LINEBR, NULL_BL_T_LINEBR };

