// The Parser: turns tokens into events.  A faithful port of PyYAML's parser.py.

import { ParserError } from './errors.mjs';
import {
  AliasEvent, DocumentEndEvent, DocumentStartEvent, MappingEndEvent,
  MappingStartEvent, ScalarEvent, SequenceEndEvent, SequenceStartEvent,
  StreamEndEvent, StreamStartEvent,
} from './events.mjs';
import { pyReprString } from './pyrepr.mjs';
import { Scanner } from './scanner.mjs';
import {
  AliasToken, AnchorToken, BlockEndToken, BlockEntryToken, BlockMappingStartToken,
  BlockSequenceStartToken, DirectiveToken, DocumentEndToken, DocumentStartToken,
  FlowEntryToken, FlowMappingEndToken, FlowMappingStartToken, FlowSequenceEndToken,
  FlowSequenceStartToken, KeyToken, ScalarToken, StreamEndToken, TagToken, ValueToken,
} from './tokens.mjs';

const DEFAULT_TAGS = { '!': '!', '!!': 'tag:yaml.org,2002:' };

export class Parser extends Scanner {
  constructor(stream) {
    super(stream);
    this.currentEvent = null;
    this.yamlVersion = null;
    this.tagHandles = {};
    this.states = [];
    this.marks = [];
    this.state = 'parseStreamStart';
  }

  checkEvent(...choices) {
    if (this.currentEvent === null) {
      if (this.state) this.currentEvent = this[this.state]();
    }
    if (this.currentEvent !== null) {
      if (!choices.length) return true;
      for (const choice of choices) {
        if (this.currentEvent instanceof choice) return true;
      }
    }
    return false;
  }

  peekEvent() {
    if (this.currentEvent === null) {
      if (this.state) this.currentEvent = this[this.state]();
    }
    return this.currentEvent;
  }

  getEvent() {
    if (this.currentEvent === null) {
      if (this.state) this.currentEvent = this[this.state]();
    }
    const value = this.currentEvent;
    this.currentEvent = null;
    return value;
  }

  // -- states ----------------------------------------------------------------

  parseStreamStart() {
    const token = this.getToken();
    const event = new StreamStartEvent(token.startMark, token.endMark, token.encoding);
    this.state = 'parseImplicitDocumentStart';
    return event;
  }

  parseImplicitDocumentStart() {
    if (!this.checkToken(DirectiveToken, DocumentStartToken, StreamEndToken)) {
      this.tagHandles = Object.assign({}, DEFAULT_TAGS);
      const token = this.peekToken();
      const startMark = token.startMark;
      const event = new DocumentStartEvent(startMark, startMark, false, null, null);
      this.states.push('parseDocumentEnd');
      this.state = 'parseBlockNodeState';
      return event;
    }
    return this.parseDocumentStart();
  }

  parseDocumentStart() {
    while (this.checkToken(DocumentEndToken)) this.getToken();
    let event;
    if (!this.checkToken(StreamEndToken)) {
      let token = this.peekToken();
      const startMark = token.startMark;
      const [version, tags] = this.processDirectives();
      if (!this.checkToken(DocumentStartToken)) {
        throw new ParserError(null, null,
          "expected '<document start>', but found "
          + pyReprString(this.peekToken().constructor.tid),
          this.peekToken().startMark);
      }
      token = this.getToken();
      const endMark = token.endMark;
      event = new DocumentStartEvent(startMark, endMark, true, version, tags);
      this.states.push('parseDocumentEnd');
      this.state = 'parseDocumentContent';
    } else {
      const token = this.getToken();
      event = new StreamEndEvent(token.startMark, token.endMark);
      this.state = null;
    }
    return event;
  }

  parseDocumentEnd() {
    let token = this.peekToken();
    const startMark = token.startMark;
    let endMark = startMark;
    let explicit = false;
    if (this.checkToken(DocumentEndToken)) {
      token = this.getToken();
      endMark = token.endMark;
      explicit = true;
    }
    const event = new DocumentEndEvent(startMark, endMark, explicit);
    this.state = 'parseDocumentStart';
    return event;
  }

  parseDocumentContent() {
    if (this.checkToken(DirectiveToken, DocumentStartToken, DocumentEndToken,
      StreamEndToken)) {
      const event = this.processEmptyScalar(this.peekToken().startMark);
      this.state = this.states.pop();
      return event;
    }
    return this.parseBlockNode();
  }

  processDirectives() {
    this.yamlVersion = null;
    this.tagHandles = {};
    while (this.checkToken(DirectiveToken)) {
      const token = this.getToken();
      if (token.tname === 'YAML') {
        if (this.yamlVersion !== null) {
          throw new ParserError(null, null, 'found duplicate YAML directive',
            token.startMark);
        }
        const [major] = token.value;
        if (major !== 1) {
          throw new ParserError(null, null,
            'found incompatible YAML document (version 1.* is required)',
            token.startMark);
        }
        this.yamlVersion = token.value;
      } else if (token.tname === 'TAG') {
        const [handle, prefix] = token.value;
        if (Object.prototype.hasOwnProperty.call(this.tagHandles, handle)) {
          throw new ParserError(null, null,
            'duplicate tag handle ' + pyReprString(handle), token.startMark);
        }
        this.tagHandles[handle] = prefix;
      }
    }
    let value;
    if (Object.keys(this.tagHandles).length) {
      value = [this.yamlVersion, Object.assign({}, this.tagHandles)];
    } else {
      value = [this.yamlVersion, null];
    }
    for (const key of Object.keys(DEFAULT_TAGS)) {
      if (!Object.prototype.hasOwnProperty.call(this.tagHandles, key)) {
        this.tagHandles[key] = DEFAULT_TAGS[key];
      }
    }
    return value;
  }

  parseBlockNodeState() {
    return this.parseBlockNode();
  }

  parseBlockNode() {
    return this.parseNode(true, false);
  }

  parseFlowNode() {
    return this.parseNode(false, false);
  }

  parseBlockNodeOrIndentlessSequence() {
    return this.parseNode(true, true);
  }

  parseNode(block = false, indentlessSequence = false) {
    let event;
    if (this.checkToken(AliasToken)) {
      const token = this.getToken();
      event = new AliasEvent(token.value, token.startMark, token.endMark);
      this.state = this.states.pop();
      return event;
    }
    let anchor = null;
    let tag = null;
    let startMark = null;
    let endMark = null;
    let tagMark = null;
    if (this.checkToken(AnchorToken)) {
      let token = this.getToken();
      startMark = token.startMark;
      endMark = token.endMark;
      anchor = token.value;
      if (this.checkToken(TagToken)) {
        token = this.getToken();
        tagMark = token.startMark;
        endMark = token.endMark;
        tag = token.value;
      }
    } else if (this.checkToken(TagToken)) {
      let token = this.getToken();
      startMark = token.startMark;
      tagMark = token.startMark;
      endMark = token.endMark;
      tag = token.value;
      if (this.checkToken(AnchorToken)) {
        token = this.getToken();
        endMark = token.endMark;
        anchor = token.value;
      }
    }
    if (tag !== null) {
      const [handle, suffix] = tag;
      if (handle !== null) {
        if (!Object.prototype.hasOwnProperty.call(this.tagHandles, handle)) {
          throw new ParserError('while parsing a node', startMark,
            'found undefined tag handle ' + pyReprString(handle), tagMark);
        }
        tag = this.tagHandles[handle] + suffix;
      } else {
        tag = suffix;
      }
    }
    if (startMark === null) {
      startMark = this.peekToken().startMark;
      endMark = startMark;
    }
    let implicit = (tag === null || tag === '!');
    if (indentlessSequence && this.checkToken(BlockEntryToken)) {
      endMark = this.peekToken().endMark;
      event = new SequenceStartEvent(anchor, tag, implicit, startMark, endMark, null);
      this.state = 'parseIndentlessSequenceEntry';
      return event;
    }
    if (this.checkToken(ScalarToken)) {
      const token = this.getToken();
      endMark = token.endMark;
      let scalarImplicit;
      if ((token.plain && tag === null) || tag === '!') {
        scalarImplicit = [true, false];
      } else if (tag === null) {
        scalarImplicit = [false, true];
      } else {
        scalarImplicit = [false, false];
      }
