// The Composer: turns events into a node graph.  Port of PyYAML's composer.py.

import { ComposerError } from './errors.mjs';
import {
  AliasEvent, MappingEndEvent, MappingStartEvent, ScalarEvent,
  SequenceEndEvent, SequenceStartEvent, StreamEndEvent, StreamStartEvent,
} from './events.mjs';
import { MappingNode, ScalarNode, SequenceNode } from './nodes.mjs';
import { Parser } from './parser.mjs';
import { pyReprString } from './pyrepr.mjs';

export class Composer extends Parser {
  constructor(stream) {
    super(stream);
    this.anchors = new Map();
  }

  checkNode() {
    if (this.checkEvent(StreamStartEvent)) this.getEvent();
    return !this.checkEvent(StreamEndEvent);
  }

  getNode() {
    if (!this.checkEvent(StreamEndEvent)) return this.composeDocument();
    return null;
  }

  getSingleNode() {
    this.getEvent();
    let document = null;
    if (!this.checkEvent(StreamEndEvent)) document = this.composeDocument();
    if (!this.checkEvent(StreamEndEvent)) {
      const event = this.getEvent();
      throw new ComposerError('expected a single document in the stream',
        document.startMark, 'but found another document', event.startMark);
    }
    this.getEvent();
    return document;
  }

  composeDocument() {
    this.getEvent();
    const node = this.composeNode(null, null);
    this.getEvent();
    this.anchors = new Map();
    return node;
  }

  composeNode(parent, index) {
    if (this.checkEvent(AliasEvent)) {
      const event = this.getEvent();
      const anchor = event.anchor;
      if (!this.anchors.has(anchor)) {
        throw new ComposerError(null, null,
          'found undefined alias ' + pyReprString(anchor), event.startMark);
      }
      return this.anchors.get(anchor);
    }
    const event = this.peekEvent();
    const anchor = event.anchor;
    if (anchor !== null && anchor !== undefined) {
      if (this.anchors.has(anchor)) {
        throw new ComposerError('found duplicate anchor ' + pyReprString(anchor)
          + '; first occurrence', this.anchors.get(anchor).startMark,
        'second occurrence', event.startMark);
      }
    }
    this.descendResolver(parent, index);
    let node = null;
    if (this.checkEvent(ScalarEvent)) {
      node = this.composeScalarNode(anchor);
    } else if (this.checkEvent(SequenceStartEvent)) {
      node = this.composeSequenceNode(anchor);
    } else if (this.checkEvent(MappingStartEvent)) {
      node = this.composeMappingNode(anchor);
    }
    this.ascendResolver();
    return node;
  }

  composeScalarNode(anchor) {
    const event = this.getEvent();
    let tag = event.tag;
    if (tag === null || tag === '!') {
      tag = this.resolve(ScalarNode, event.value, event.implicit);
    }
    const node = new ScalarNode(tag, event.value, event.startMark, event.endMark,
      event.style);
    if (anchor !== null && anchor !== undefined) this.anchors.set(anchor, node);
    return node;
  }

  composeSequenceNode(anchor) {
    const startEvent = this.getEvent();
    let tag = startEvent.tag;
    if (tag === null || tag === '!') {
      tag = this.resolve(SequenceNode, null, startEvent.implicit);
    }
    const node = new SequenceNode(tag, [], startEvent.startMark, null,
      startEvent.flowStyle);
    if (anchor !== null && anchor !== undefined) this.anchors.set(anchor, node);
    let index = 0;
    while (!this.checkEvent(SequenceEndEvent)) {
      node.value.push(this.composeNode(node, index));
      index += 1;
    }
    const endEvent = this.getEvent();
    node.endMark = endEvent.endMark;
    return node;
  }

  composeMappingNode(anchor) {
    const startEvent = this.getEvent();
    let tag = startEvent.tag;
    if (tag === null || tag === '!') {
      tag = this.resolve(MappingNode, null, startEvent.implicit);
    }
    const node = new MappingNode(tag, [], startEvent.startMark, null,
      startEvent.flowStyle);
    if (anchor !== null && anchor !== undefined) this.anchors.set(anchor, node);
    while (!this.checkEvent(MappingEndEvent)) {
      const itemKey = this.composeNode(node, null);
      const itemValue = this.composeNode(node, itemKey);
      node.value.push([itemKey, itemValue]);
    }
    const endEvent = this.getEvent();
    node.endMark = endEvent.endMark;
    return node;
  }
}

