// The SafeConstructor: turns nodes into Python-like values.  Port of the safe
// half of PyYAML's constructor.py.

import { TAB } from './chars.mjs';
import { Composer } from './composer.mjs';
import { ConstructorError, PyValueError } from './errors.mjs';
import { MappingNode, ScalarNode, SequenceNode } from './nodes.mjs';
import {
  base64Decode, BinasciiError, pyReprString, utf8Encode,
} from './pyrepr.mjs';
import { parseTimestamp } from './resolver.mjs';
import {
  hashKey, NONE, PyBytes, PyDate, PyDateTime, PyDict, PyFloat, PySet, PyTuple,
  UnhashableError,
} from './pytypes.mjs';

const T = 'tag:yaml.org,2002:';

const BOOL_VALUES = new Map([
  ['yes', true], ['no', false], ['true', true], ['false', false],
  ['on', true], ['off', false],
]);

// float('inf') as PyYAML computes it.
const INF_VALUE = Infinity;

function nodeId(node) {
  if (node instanceof ScalarNode) return 'scalar';
  if (node instanceof SequenceNode) return 'sequence';
  if (node instanceof MappingNode) return 'mapping';
  return 'node';
}

function isGenerator(obj) {
  return obj !== null && typeof obj === 'object'
    && typeof obj.next === 'function' && typeof obj.throw === 'function';
}

export class Constructor extends Composer {
  constructor(stream) {
    super(stream);
    this.constructedObjects = new Map();
    this.recursiveObjects = new Map();
    this.stateGenerators = [];
    this.deepConstruct = false;
  }

  checkData() {
    return this.checkNode();
  }

  getData() {
    if (this.checkNode()) return this.constructDocument(this.getNode());
    return undefined;
  }

  getSingleData() {
    const node = this.getSingleNode();
    if (node !== null) return this.constructDocument(node);
    return NONE;
  }

  constructDocument(node) {
    const data = this.constructObject(node, false);
    while (this.stateGenerators.length) {
      const generators = this.stateGenerators;
      this.stateGenerators = [];
      for (const generator of generators) {
        // Exhaust the generator; the second half fills the container in place.
        let step = generator.next();
        while (!step.done) step = generator.next();
      }
    }
    this.constructedObjects = new Map();
    this.recursiveObjects = new Map();
    this.deepConstruct = false;
    return data;
  }

  constructObject(node, deep = false) {
    if (this.constructedObjects.has(node)) return this.constructedObjects.get(node);
    let oldDeep = false;
    if (deep) {
      oldDeep = this.deepConstruct;
      this.deepConstruct = true;
    }
    if (this.recursiveObjects.has(node)) {
      throw new ConstructorError(null, null, 'found unconstructable recursive node',
        node.startMark);
    }
    this.recursiveObjects.set(node, null);
    const handler = this.pickConstructor(node);
    let data = handler.call(this, node);
    if (isGenerator(data)) {
      const generator = data;
      data = generator.next().value;
      if (this.deepConstruct) {
        let step = generator.next();
        while (!step.done) step = generator.next();
      } else {
        this.stateGenerators.push(generator);
      }
    }
    this.constructedObjects.set(node, data);
    this.recursiveObjects.delete(node);
    if (deep) this.deepConstruct = oldDeep;
    return data;
  }

  pickConstructor(node) {
    const table = this.constructor.yamlConstructors;
    if (table.has(node.tag)) return table.get(node.tag);
    return table.get(null);
  }

  // -- base constructors -----------------------------------------------------

  baseConstructScalar(node) {
    if (!(node instanceof ScalarNode)) {
      throw new ConstructorError(null, null,
        'expected a scalar node, but found ' + nodeId(node), node.startMark);
    }
    return node.value;
  }

  constructScalar(node) {
    if (node instanceof MappingNode) {
      for (const [keyNode, valueNode] of node.value) {
        if (keyNode.tag === T + 'value') return this.constructScalar(valueNode);
      }
    }
    return this.baseConstructScalar(node);
  }

  constructSequence(node, deep = false) {
    if (!(node instanceof SequenceNode)) {
      throw new ConstructorError(null, null,
        'expected a sequence node, but found ' + nodeId(node), node.startMark);
    }
    const out = [];
    for (const child of node.value) out.push(this.constructObject(child, deep));
    return out;
  }

  baseConstructMapping(node, deep = false) {
    if (!(node instanceof MappingNode)) {
      throw new ConstructorError(null, null,
        'expected a mapping node, but found ' + nodeId(node), node.startMark);
    }
    const mapping = new PyDict();
    for (const [keyNode, valueNode] of node.value) {
      const key = this.constructObject(keyNode, deep);
      try {
        hashKey(key);
      } catch (exc) {
        if (exc instanceof UnhashableError) {
          throw new ConstructorError('while constructing a mapping', node.startMark,
            'found unhashable key', keyNode.startMark);
        }
        throw exc;
      }
      const value = this.constructObject(valueNode, deep);
      mapping.setItem(key, value);
    }
    return mapping;
  }

  constructMapping(node, deep = false) {
    if (node instanceof MappingNode) this.flattenMapping(node);
    return this.baseConstructMapping(node, deep);
  }

  constructPairs(node, deep = false) {
    if (!(node instanceof MappingNode)) {
      throw new ConstructorError(null, null,
        'expected a mapping node, but found ' + nodeId(node), node.startMark);
    }
    const pairs = [];
    for (const [keyNode, valueNode] of node.value) {
      const key = this.constructObject(keyNode, deep);
      const value = this.constructObject(valueNode, deep);
      pairs.push(new PyTuple([key, value]));
    }
    return pairs;
  }

  flattenMapping(node) {
    const merge = [];
    let index = 0;
    while (index < node.value.length) {
      const [keyNode, valueNode] = node.value[index];
      if (keyNode.tag === T + 'merge') {
        node.value.splice(index, 1);
        if (valueNode instanceof MappingNode) {
          this.flattenMapping(valueNode);
          for (const item of valueNode.value) merge.push(item);
        } else if (valueNode instanceof SequenceNode) {
          const submerge = [];
          for (const subnode of valueNode.value) {
            if (!(subnode instanceof MappingNode)) {
              throw new ConstructorError('while constructing a mapping',
                node.startMark,
                'expected a mapping for merging, but found ' + nodeId(subnode),
                subnode.startMark);
            }
            this.flattenMapping(subnode);
            submerge.push(subnode.value);
          }
          submerge.reverse();
          for (const value of submerge) for (const item of value) merge.push(item);
        } else {
          throw new ConstructorError('while constructing a mapping', node.startMark,
            'expected a mapping or list of mappings for merging, but found '
            + nodeId(valueNode), valueNode.startMark);
        }
      } else if (keyNode.tag === T + 'value') {
        keyNode.tag = T + 'str';
        index += 1;
      } else {
        index += 1;
      }
    }
    if (merge.length) node.value = merge.concat(node.value);
  }

  // -- tag constructors ------------------------------------------------------

  constructYamlNull(node) {
    this.constructScalar(node);
    return NONE;
  }

  constructYamlBool(node) {
    const value = this.constructScalar(node);
    const key = value.toLowerCase();
    if (!BOOL_VALUES.has(key)) {
      const err = new Error(pyReprString(key));
      err.pyType = 'KeyError';
      err.pyStr = () => pyReprString(key);
      throw err;
    }
    return BOOL_VALUES.get(key);
  }

  constructYamlInt(node) {
    let value = this.constructScalar(node);
    value = value.split('_').join('');
    let sign = 1n;
    if (value.charAt(0) === '-') sign = -1n;
    if (value.charAt(0) === '+' || value.charAt(0) === '-') value = value.slice(1);
    if (value === '0') return 0n;
    if (value.slice(0, 2) === '0b') return sign * pyBigInt(value.slice(2), 2, value);
    if (value.slice(0, 2) === '0x') return sign * pyBigInt(value.slice(2), 16, value);
    if (value.charAt(0) === '0') return sign * pyBigInt(value, 8, value);
    if (value.indexOf(':') !== -1) {
      const digits = value.split(':').map((part) => pyBigInt(part, 10, part));
      digits.reverse();
      let base = 1n;
      let total = 0n;
      for (const digit of digits) {
        total += digit * base;
        base *= 60n;
      }
      return sign * total;
    }
    return sign * pyBigInt(value, 10, value);
  }

  constructYamlFloat(node) {
    let value = this.constructScalar(node);
    value = value.split('_').join('').toLowerCase();
    let sign = 1;
    if (value.charAt(0) === '-') sign = -1;
    if (value.charAt(0) === '+' || value.charAt(0) === '-') value = value.slice(1);
    if (value === '.inf') return new PyFloat(sign * INF_VALUE);
    if (value === '.nan') return new PyFloat(NaN);
    if (value.indexOf(':') !== -1) {
      const digits = value.split(':').map((part) => pyFloatOf(part));
      digits.reverse();
      let base = 1;
      let total = 0;
      for (const digit of digits) {
        total += digit * base;
        base *= 60;
      }
      return new PyFloat(sign * total);
    }
    return new PyFloat(sign * pyFloatOf(value));
  }

  constructYamlBinary(node) {
    const value = this.constructScalar(node);
    for (const ch of value) {
      if (ch.codePointAt(0) > 127) {
        throw new ConstructorError(null, null,
          'failed to convert base64 data into ascii: '
          + "'ascii' codec can't encode character " + pyReprString(ch)
          + ' in position ' + Array.from(value).indexOf(ch)
          + ': ordinal not in range(128)', node.startMark);
      }
    }
    try {
      return new PyBytes(base64Decode(value));
    } catch (exc) {
      if (exc instanceof BinasciiError) {
        throw new ConstructorError(null, null,
          'failed to decode base64 data: ' + exc.message, node.startMark);
      }
      throw exc;
    }
  }

  constructYamlTimestamp(node) {
    this.constructScalar(node);
    const values = parseTimestamp(node.value);
    const year = Number(values.year);
    const month = Number(values.month);
    const day = Number(values.day);
    if (!values.hour) return new PyDate(year, month, day);
    const hour = Number(values.hour);
    const minute = Number(values.minute);
    const second = Number(values.second);
    let fraction = 0;
    let tzMinutes = null;
    if (values.fraction) {
      let frac = values.fraction.slice(0, 6);
      while (frac.length < 6) frac += '0';
      fraction = Number(frac);
      if (values.fraction.length > 6 && Number(values.fraction.charAt(6)) > 4) {
        fraction += 1;
      }
    }
    if (values.tzSign) {
      const tzHour = Number(values.tzHour);
      const tzMinute = values.tzMinute ? Number(values.tzMinute) : 0;
      let delta = tzHour * 60 + tzMinute;
      if (values.tzSign === '-') delta = -delta;
      tzMinutes = delta;
    } else if (values.tz) {
      tzMinutes = 0;
    }
    return new PyDateTime(year, month, day, hour, minute, second, fraction, tzMinutes);
  }

  * constructYamlOmap(node) {
    const omap = [];
    yield omap;
    if (!(node instanceof SequenceNode)) {
      throw new ConstructorError('while constructing an ordered map', node.startMark,
        'expected a sequence, but found ' + nodeId(node), node.startMark);
    }
    for (const subnode of node.value) {
      if (!(subnode instanceof MappingNode)) {
        throw new ConstructorError('while constructing an ordered map', node.startMark,
          'expected a mapping of length 1, but found ' + nodeId(subnode),
          subnode.startMark);
      }
      if (subnode.value.length !== 1) {
        throw new ConstructorError('while constructing an ordered map', node.startMark,
          'expected a single mapping item, but found ' + subnode.value.length
          + ' items', subnode.startMark);
