      const [keyNode, valueNode] = subnode.value[0];
      const key = this.constructObject(keyNode, false);
      const value = this.constructObject(valueNode, false);
      omap.push(new PyTuple([key, value]));
    }
  }

  * constructYamlPairs(node) {
    const pairs = [];
    yield pairs;
    if (!(node instanceof SequenceNode)) {
      throw new ConstructorError('while constructing pairs', node.startMark,
        'expected a sequence, but found ' + nodeId(node), node.startMark);
    }
    for (const subnode of node.value) {
      if (!(subnode instanceof MappingNode)) {
        throw new ConstructorError('while constructing pairs', node.startMark,
          'expected a mapping of length 1, but found ' + nodeId(subnode),
          subnode.startMark);
      }
      if (subnode.value.length !== 1) {
        throw new ConstructorError('while constructing pairs', node.startMark,
          'expected a single mapping item, but found ' + subnode.value.length
          + ' items', subnode.startMark);
      }
      const [keyNode, valueNode] = subnode.value[0];
      const key = this.constructObject(keyNode, false);
      const value = this.constructObject(valueNode, false);
      pairs.push(new PyTuple([key, value]));
    }
  }

  * constructYamlSet(node) {
    const data = new PySet();
    yield data;
    const value = this.constructMapping(node, false);
    for (const [key] of value.entries) data.add(key);
  }

  constructYamlStr(node) {
    return this.constructScalar(node);
  }

  * constructYamlSeq(node) {
    const data = [];
    yield data;
    const value = this.constructSequence(node, false);
    for (const item of value) data.push(item);
  }

  * constructYamlMap(node) {
    const data = new PyDict();
    yield data;
    const value = this.constructMapping(node, false);
    data.update(value);
  }

  constructUndefined(node) {
    throw new ConstructorError(null, null,
      'could not determine a constructor for the tag ' + pyReprString(node.tag),
      node.startMark);
