// int(text, base) with Python's error message.
function pyBigInt(text, base, original) {
  const digits = '0123456789abcdefghijklmnopqrstuvwxyz'.slice(0, base);
  if (text.length === 0) throw invalidInt(base, original);
  let i = 0;
  let sign = 1n;
  if (text.charAt(0) === '+' || text.charAt(0) === '-') {
    if (text.charAt(0) === '-') sign = -1n;
    i = 1;
  }
  if (i >= text.length) throw invalidInt(base, original);
  let value = 0n;
  const big = BigInt(base);
  for (; i < text.length; i += 1) {
    const ch = text.charAt(i).toLowerCase();
    const d = digits.indexOf(ch);
    if (d === -1) throw invalidInt(base, original);
    value = value * big + BigInt(d);
