  [T + 'omap', Constructor.prototype.constructYamlOmap],
  [T + 'pairs', Constructor.prototype.constructYamlPairs],
  [T + 'set', Constructor.prototype.constructYamlSet],
  [T + 'str', Constructor.prototype.constructYamlStr],
  [T + 'seq', Constructor.prototype.constructYamlSeq],
