      seenDot = true;
    } else if ((ch === 'e' || ch === 'E') && seenDigit && !seenExp) {
      seenExp = true;
      seenDigit = false;
      if (i + 1 < trimmed.length
        && (trimmed.charAt(i + 1) === '+' || trimmed.charAt(i + 1) === '-')) {
        i += 1;
      }
    } else {
      ok = false;
      break;
    }
  }
  if (!ok || !seenDigit) {
    const lowered = trimmed.toLowerCase();
    if (lowered === 'inf' || lowered === 'infinity' || lowered === '+inf'
      || lowered === '+infinity') return Infinity;
    if (lowered === '-inf' || lowered === '-infinity') return -Infinity;
    if (lowered === 'nan' || lowered === '+nan' || lowered === '-nan') return NaN;
    throw new PyValueError('could not convert string to float: ' + pyReprString(text));
  }
  return Number(trimmed);
}

