// The Emitter: turns events into text.  A faithful port of PyYAML's emitter.py.
// All text is handled as arrays of code points so that lengths and columns
// match Python's string indices exactly.

import { CR, LF, LINE_BREAKS, NUL, SPACE, TAB } from './chars.mjs';
import { EmitterError } from './errors.mjs';
import {
  AliasEvent, CollectionEndEvent, CollectionStartEvent, DocumentEndEvent,
  DocumentStartEvent, MappingStartEvent, NodeEvent, ScalarEvent,
  SequenceEndEvent, MappingEndEvent, SequenceStartEvent, StreamEndEvent,
  StreamStartEvent,
} from './events.mjs';

const NULL_BL_T_LINEBR = NUL + SPACE + TAB + CR + LINE_BREAKS;

function isBreak(ch) {
  return ch === LF || LINE_BREAKS.indexOf(ch) !== -1;
}

function isSpaceTabBreakNul(ch) {
  return NULL_BL_T_LINEBR.indexOf(ch) !== -1;
}

const DEFAULT_TAG_PREFIXES = { '!': '!', 'tag:yaml.org,2002:': '!!' };

const ESCAPE_REPLACEMENTS = new Map([
  [String.fromCharCode(0x00), '0'],
  [String.fromCharCode(0x07), 'a'],
  [String.fromCharCode(0x08), 'b'],
  [String.fromCharCode(0x09), 't'],
  [String.fromCharCode(0x0a), 'n'],
  [String.fromCharCode(0x0b), 'v'],
  [String.fromCharCode(0x0c), 'f'],
  [String.fromCharCode(0x0d), 'r'],
  [String.fromCharCode(0x1b), 'e'],
  ['"', '"'],
  ['\\', '\\'],
  [String.fromCharCode(0x85), 'N'],
  [String.fromCharCode(0xa0), '_'],
  [String.fromCharCode(0x2028), 'L'],
  [String.fromCharCode(0x2029), 'P'],
]);

class ScalarAnalysis {
  constructor(scalar, empty, multiline, allowFlowPlain, allowBlockPlain,
    allowSingleQuoted, allowDoubleQuoted, allowBlock) {
    this.scalar = scalar;
    this.empty = empty;
    this.multiline = multiline;
    this.allowFlowPlain = allowFlowPlain;
    this.allowBlockPlain = allowBlockPlain;
    this.allowSingleQuoted = allowSingleQuoted;
    this.allowDoubleQuoted = allowDoubleQuoted;
    this.allowBlock = allowBlock;
  }
}

function hexUpper(cp, width) {
  let hex = cp.toString(16).toUpperCase();
  while (hex.length < width) hex = '0' + hex;
  return hex;
}

export class Emitter {
  constructor(stream, options = {}) {
    this.stream = stream;
    this.encoding = null;
    this.states = [];
    this.state = 'expectStreamStart';
    this.events = [];
    this.event = null;
    this.indents = [];
    this.indent = null;
    this.flowLevel = 0;
    this.rootContext = false;
    this.sequenceContext = false;
    this.mappingContext = false;
    this.simpleKeyContext = false;
    this.line = 0;
    this.column = 0;
    this.whitespace = true;
    this.indention = true;
    this.openEnded = false;
    this.canonical = options.canonical || null;
    this.allowUnicode = options.allowUnicode === undefined ? null : options.allowUnicode;
    this.bestIndent = 2;
    if (options.indent && options.indent > 1 && options.indent < 10) {
      this.bestIndent = options.indent;
    }
    this.bestWidth = 80;
    if (options.width && options.width > this.bestIndent * 2) {
      this.bestWidth = options.width;
    }
    this.bestLineBreak = LF;
    if (options.lineBreak === CR || options.lineBreak === LF
      || options.lineBreak === CR + LF) {
      this.bestLineBreak = options.lineBreak;
    }
    this.tagPrefixes = null;
    this.preparedAnchor = null;
    this.preparedTag = null;
    this.analysis = null;
    this.style = null;
  }

  emit(event) {
    this.events.push(event);
    while (!this.needMoreEvents()) {
      this.event = this.events.shift();
      this[this.state]();
      this.event = null;
    }
  }

  needMoreEvents() {
    if (!this.events.length) return true;
    const event = this.events[0];
    if (event instanceof DocumentStartEvent) return this.needEvents(1);
    if (event instanceof SequenceStartEvent) return this.needEvents(2);
    if (event instanceof MappingStartEvent) return this.needEvents(3);
    return false;
  }

  needEvents(count) {
    let level = 0;
    for (let i = 1; i < this.events.length; i += 1) {
      const event = this.events[i];
      if (event instanceof DocumentStartEvent || event instanceof CollectionStartEvent) {
        level += 1;
      } else if (event instanceof DocumentEndEvent
        || event instanceof CollectionEndEvent) {
        level -= 1;
      } else if (event instanceof StreamEndEvent) {
        level = -1;
      }
      if (level < 0) return false;
    }
    return this.events.length < count + 1;
  }

  increaseIndent(flow = false, indentless = false) {
    this.indents.push(this.indent);
    if (this.indent === null) {
      this.indent = flow ? this.bestIndent : 0;
    } else if (!indentless) {
      this.indent += this.bestIndent;
    }
  }

  // -- states ----------------------------------------------------------------

  expectStreamStart() {
    if (this.event instanceof StreamStartEvent) {
      this.writeStreamStart();
      this.state = 'expectFirstDocumentStart';
    } else {
      throw new EmitterError('expected StreamStartEvent, but got ' + this.event);
    }
  }

  expectNothing() {
    throw new EmitterError('expected nothing, but got ' + this.event);
  }

  expectFirstDocumentStart() {
    return this.expectDocumentStart(true);
  }

  expectDocumentStartState() {
    return this.expectDocumentStart(false);
  }

  expectDocumentStart(first = false) {
    if (this.event instanceof DocumentStartEvent) {
      if ((this.event.version || this.event.tags) && this.openEnded) {
        this.writeIndicator('...', true);
        this.writeIndent();
      }
      if (this.event.version) {
        this.writeVersionDirective(this.prepareVersion(this.event.version));
      }
      this.tagPrefixes = Object.assign({}, DEFAULT_TAG_PREFIXES);
      if (this.event.tags) {
        const handles = Object.keys(this.event.tags).sort();
        for (const handle of handles) {
          const prefix = this.event.tags[handle];
          this.tagPrefixes[prefix] = handle;
          this.writeTagDirective(this.prepareTagHandle(handle),
            this.prepareTagPrefix(prefix));
        }
      }
      const implicit = first && !this.event.explicit && !this.canonical
        && !this.event.version && !this.event.tags && !this.checkEmptyDocument();
      if (!implicit) {
        this.writeIndent();
        this.writeIndicator('---', true);
        if (this.canonical) this.writeIndent();
      }
      this.state = 'expectDocumentRoot';
    } else if (this.event instanceof StreamEndEvent) {
      if (this.openEnded) {
        this.writeIndicator('...', true);
        this.writeIndent();
      }
      this.writeStreamEnd();
      this.state = 'expectNothing';
    } else {
      throw new EmitterError('expected DocumentStartEvent, but got ' + this.event);
    }
    return undefined;
  }

  expectDocumentEnd() {
    if (this.event instanceof DocumentEndEvent) {
      this.writeIndent();
      if (this.event.explicit) {
        this.writeIndicator('...', true);
        this.writeIndent();
      }
      this.flushStream();
      this.state = 'expectDocumentStartState';
    } else {
      throw new EmitterError('expected DocumentEndEvent, but got ' + this.event);
    }
  }

  expectDocumentRoot() {
    this.states.push('expectDocumentEnd');
    this.expectNode(true, false, false, false);
  }

  expectNode(root = false, sequence = false, mapping = false, simpleKey = false) {
    this.rootContext = root;
    this.sequenceContext = sequence;
    this.mappingContext = mapping;
    this.simpleKeyContext = simpleKey;
    if (this.event instanceof AliasEvent) {
      this.expectAlias();
    } else if (this.event instanceof ScalarEvent
      || this.event instanceof CollectionStartEvent) {
      this.processAnchor('&');
      this.processTag();
      if (this.event instanceof ScalarEvent) {
        this.expectScalar();
      } else if (this.event instanceof SequenceStartEvent) {
        if (this.flowLevel || this.canonical || this.event.flowStyle
          || this.checkEmptySequence()) {
          this.expectFlowSequence();
        } else {
          this.expectBlockSequence();
        }
      } else if (this.event instanceof MappingStartEvent) {
        if (this.flowLevel || this.canonical || this.event.flowStyle
          || this.checkEmptyMapping()) {
          this.expectFlowMapping();
        } else {
          this.expectBlockMapping();
        }
      }
    } else {
      throw new EmitterError('expected NodeEvent, but got ' + this.event);
    }
  }

  expectAlias() {
    if (this.event.anchor === null) {
      throw new EmitterError('anchor is not specified for alias');
    }
    this.processAnchor('*');
    this.state = this.states.pop();
  }

  expectScalar() {
    this.increaseIndent(true, false);
    this.processScalar();
    this.indent = this.indents.pop();
    this.state = this.states.pop();
  }

  // -- flow sequence ---------------------------------------------------------

  expectFlowSequence() {
    this.writeIndicator('[', true, true, false);
    this.flowLevel += 1;
    this.increaseIndent(true, false);
    this.state = 'expectFirstFlowSequenceItem';
  }

  expectFirstFlowSequenceItem() {
    if (this.event instanceof SequenceEndEvent) {
      this.indent = this.indents.pop();
      this.flowLevel -= 1;
      this.writeIndicator(']', false, false, false);
      this.state = this.states.pop();
    } else {
      if (this.canonical || this.column > this.bestWidth) this.writeIndent();
      this.states.push('expectFlowSequenceItem');
      this.expectNode(false, true, false, false);
    }
  }

  expectFlowSequenceItem() {
    if (this.event instanceof SequenceEndEvent) {
      this.indent = this.indents.pop();
      this.flowLevel -= 1;
      if (this.canonical) {
        this.writeIndicator(',', false, false, false);
        this.writeIndent();
      }
      this.writeIndicator(']', false, false, false);
      this.state = this.states.pop();
    } else {
      this.writeIndicator(',', false, false, false);
      if (this.canonical || this.column > this.bestWidth) this.writeIndent();
      this.states.push('expectFlowSequenceItem');
      this.expectNode(false, true, false, false);
    }
  }

  // -- flow mapping ----------------------------------------------------------

  expectFlowMapping() {
    this.writeIndicator('{', true, true, false);
    this.flowLevel += 1;
    this.increaseIndent(true, false);
    this.state = 'expectFirstFlowMappingKey';
  }

  expectFirstFlowMappingKey() {
    if (this.event instanceof MappingEndEvent) {
      this.indent = this.indents.pop();
      this.flowLevel -= 1;
      this.writeIndicator('}', false, false, false);
      this.state = this.states.pop();
    } else {
      if (this.canonical || this.column > this.bestWidth) this.writeIndent();
      if (!this.canonical && this.checkSimpleKey()) {
        this.states.push('expectFlowMappingSimpleValue');
        this.expectNode(false, false, true, true);
      } else {
        this.writeIndicator('?', true, false, false);
        this.states.push('expectFlowMappingValue');
        this.expectNode(false, false, true, false);
      }
    }
  }

  expectFlowMappingKey() {
    if (this.event instanceof MappingEndEvent) {
      this.indent = this.indents.pop();
      this.flowLevel -= 1;
      if (this.canonical) {
        this.writeIndicator(',', false, false, false);
        this.writeIndent();
      }
      this.writeIndicator('}', false, false, false);
      this.state = this.states.pop();
    } else {
      this.writeIndicator(',', false, false, false);
      if (this.canonical || this.column > this.bestWidth) this.writeIndent();
      if (!this.canonical && this.checkSimpleKey()) {
        this.states.push('expectFlowMappingSimpleValue');
        this.expectNode(false, false, true, true);
      } else {
        this.writeIndicator('?', true, false, false);
        this.states.push('expectFlowMappingValue');
        this.expectNode(false, false, true, false);
      }
    }
  }

  expectFlowMappingSimpleValue() {
    this.writeIndicator(':', false, false, false);
    this.states.push('expectFlowMappingKey');
    this.expectNode(false, false, true, false);
  }

  expectFlowMappingValue() {
    if (this.canonical || this.column > this.bestWidth) this.writeIndent();
    this.writeIndicator(':', true, false, false);
    this.states.push('expectFlowMappingKey');
    this.expectNode(false, false, true, false);
  }

  // -- block sequence --------------------------------------------------------

  expectBlockSequence() {
    const indentless = this.mappingContext && !this.indention;
    this.increaseIndent(false, indentless);
    this.state = 'expectFirstBlockSequenceItem';
  }

  expectFirstBlockSequenceItem() {
    return this.expectBlockSequenceItem(true);
  }

  expectBlockSequenceItemState() {
    return this.expectBlockSequenceItem(false);
  }

  expectBlockSequenceItem(first = false) {
    if (!first && this.event instanceof SequenceEndEvent) {
      this.indent = this.indents.pop();
      this.state = this.states.pop();
    } else {
      this.writeIndent();
      this.writeIndicator('-', true, false, true);
      this.states.push('expectBlockSequenceItemState');
      this.expectNode(false, true, false, false);
    }
    return undefined;
  }

  // -- block mapping ---------------------------------------------------------

  expectBlockMapping() {
    this.increaseIndent(false, false);
    this.state = 'expectFirstBlockMappingKey';
  }

  expectFirstBlockMappingKey() {
    return this.expectBlockMappingKey(true);
  }

  expectBlockMappingKeyState() {
    return this.expectBlockMappingKey(false);
  }

  expectBlockMappingKey(first = false) {
    if (!first && this.event instanceof MappingEndEvent) {
      this.indent = this.indents.pop();
      this.state = this.states.pop();
    } else {
      this.writeIndent();
      if (this.checkSimpleKey()) {
        this.states.push('expectBlockMappingSimpleValue');
        this.expectNode(false, false, true, true);
      } else {
        this.writeIndicator('?', true, false, true);
        this.states.push('expectBlockMappingValue');
        this.expectNode(false, false, true, false);
      }
    }
    return undefined;
  }

  expectBlockMappingSimpleValue() {
    this.writeIndicator(':', false, false, false);
    this.states.push('expectBlockMappingKeyState');
    this.expectNode(false, false, true, false);
  }

  expectBlockMappingValue() {
    this.writeIndent();
    this.writeIndicator(':', true, false, true);
    this.states.push('expectBlockMappingKeyState');
    this.expectNode(false, false, true, false);
  }

  // -- checkers --------------------------------------------------------------

  checkEmptySequence() {
    return this.event instanceof SequenceStartEvent && this.events.length
      && this.events[0] instanceof SequenceEndEvent;
  }

  checkEmptyMapping() {
    return this.event instanceof MappingStartEvent && this.events.length
      && this.events[0] instanceof MappingEndEvent;
  }

  checkEmptyDocument() {
    if (!(this.event instanceof DocumentStartEvent) || !this.events.length) {
      return false;
    }
    const event = this.events[0];
    return event instanceof ScalarEvent && event.anchor === null
      && event.tag === null && event.implicit && event.value === '';
  }

  checkSimpleKey() {
    let length = 0;
    if (this.event instanceof NodeEvent && this.event.anchor !== null) {
      if (this.preparedAnchor === null) {
        this.preparedAnchor = this.prepareAnchor(this.event.anchor);
      }
      length += Array.from(this.preparedAnchor).length;
    }
    if ((this.event instanceof ScalarEvent || this.event instanceof CollectionStartEvent)
      && this.event.tag !== null) {
      if (this.preparedTag === null) {
        this.preparedTag = this.prepareTag(this.event.tag);
      }
      length += Array.from(this.preparedTag).length;
    }
    if (this.event instanceof ScalarEvent) {
      if (this.analysis === null) this.analysis = this.analyzeScalar(this.event.value);
      length += Array.from(this.analysis.scalar).length;
    }
    return length < 128 && (this.event instanceof AliasEvent
      || (this.event instanceof ScalarEvent
        && !this.analysis.empty && !this.analysis.multiline)
      || this.checkEmptySequence() || this.checkEmptyMapping());
  }

  // -- anchor, tag and scalar processors -------------------------------------

  processAnchor(indicator) {
    if (this.event.anchor === null) {
      this.preparedAnchor = null;
      return;
    }
    if (this.preparedAnchor === null) {
      this.preparedAnchor = this.prepareAnchor(this.event.anchor);
    }
    if (this.preparedAnchor) {
      this.writeIndicator(indicator + this.preparedAnchor, true, false, false);
    }
    this.preparedAnchor = null;
  }

  processTag() {
    let tag = this.event.tag;
    if (this.event instanceof ScalarEvent) {
      if (this.style === null) this.style = this.chooseScalarStyle();
      if ((!this.canonical || tag === null)
        && ((this.style === '' && this.event.implicit[0])
          || (this.style !== '' && this.event.implicit[1]))) {
        this.preparedTag = null;
        return;
      }
      if (this.event.implicit[0] && tag === null) {
        tag = '!';
        this.preparedTag = null;
      }
    } else if ((!this.canonical || tag === null) && this.event.implicit) {
      this.preparedTag = null;
      return;
    }
    if (tag === null) throw new EmitterError('tag is not specified');
    if (this.preparedTag === null) this.preparedTag = this.prepareTag(tag);
    if (this.preparedTag) {
      this.writeIndicator(this.preparedTag, true, false, false);
    }
    this.preparedTag = null;
  }

  chooseScalarStyle() {
    if (this.analysis === null) this.analysis = this.analyzeScalar(this.event.value);
    if (this.event.style === '"' || this.canonical) return '"';
    if (!this.event.style && this.event.implicit[0]) {
      if (!(this.simpleKeyContext && (this.analysis.empty || this.analysis.multiline))
        && ((this.flowLevel && this.analysis.allowFlowPlain)
          || (!this.flowLevel && this.analysis.allowBlockPlain))) {
        return '';
      }
    }
    if (this.event.style && (this.event.style === '|' || this.event.style === '>')) {
      if (!this.flowLevel && !this.simpleKeyContext && this.analysis.allowBlock) {
        return this.event.style;
      }
    }
    if (!this.event.style || this.event.style === "'") {
      if (this.analysis.allowSingleQuoted
        && !(this.simpleKeyContext && this.analysis.multiline)) {
        return "'";
      }
    }
    return '"';
  }

  processScalar() {
    if (this.analysis === null) this.analysis = this.analyzeScalar(this.event.value);
    if (this.style === null) this.style = this.chooseScalarStyle();
    const split = !this.simpleKeyContext;
    if (this.style === '"') {
      this.writeDoubleQuoted(this.analysis.scalar, split);
    } else if (this.style === "'") {
      this.writeSingleQuoted(this.analysis.scalar, split);
    } else if (this.style === '>') {
      this.writeFolded(this.analysis.scalar);
    } else if (this.style === '|') {
      this.writeLiteral(this.analysis.scalar);
    } else {
      this.writePlain(this.analysis.scalar, split);
    }
    this.analysis = null;
    this.style = null;
  }

  // -- analyzers -------------------------------------------------------------

  prepareVersion(version) {
    const [major, minor] = version;
    if (major !== 1) {
      throw new EmitterError('unsupported YAML version: ' + major + '.' + minor);
    }
    return major + '.' + minor;
  }

  prepareTagHandle(handle) {
    if (!handle) throw new EmitterError('tag handle must not be empty');
    if (handle.charAt(0) !== '!' || handle.charAt(handle.length - 1) !== '!') {
      throw new EmitterError("tag handle must start and end with '!': " + handle);
    }
    for (const ch of handle.slice(1, -1)) {
      if (!((ch >= '0' && ch <= '9') || (ch >= 'A' && ch <= 'Z')
        || (ch >= 'a' && ch <= 'z') || ch === '-' || ch === '_')) {
        throw new EmitterError('invalid character ' + ch + ' in the tag handle: ' + handle);
      }
    }
    return handle;
  }

  prepareTagPrefix(prefix) {
    if (!prefix) throw new EmitterError('tag prefix must not be empty');
    const chunks = [];
    let start = 0;
    let end = 0;
    const chars = Array.from(prefix);
    if (chars[0] === '!') end = 1;
    while (end < chars.length) {
      const ch = chars[end];
      if ((ch >= '0' && ch <= '9') || (ch >= 'A' && ch <= 'Z')
        || (ch >= 'a' && ch <= 'z') || "-;/?!:@&=+$,_.~*'()[]".indexOf(ch) !== -1) {
        end += 1;
      } else {
        if (start < end) chunks.push(chars.slice(start, end).join(''));
        start = end + 1;
        end = start;
        chunks.push(percentEncode(ch));
      }
    }
    if (start < end) chunks.push(chars.slice(start, end).join(''));
    return chunks.join('');
  }

  prepareTag(tag) {
    if (!tag) throw new EmitterError('tag must not be empty');
    if (tag === '!') return tag;
    let handle = null;
    let suffix = tag;
    const prefixes = Object.keys(this.tagPrefixes).sort();
    for (const prefix of prefixes) {
      if (tag.slice(0, prefix.length) === prefix
        && (prefix === '!' || prefix.length < tag.length)) {
        handle = this.tagPrefixes[prefix];
        suffix = tag.slice(prefix.length);
      }
    }
    const chunks = [];
    const chars = Array.from(suffix);
    let start = 0;
    let end = 0;
    while (end < chars.length) {
      const ch = chars[end];
      if ((ch >= '0' && ch <= '9') || (ch >= 'A' && ch <= 'Z')
        || (ch >= 'a' && ch <= 'z') || "-;/?:@&=+$,_.~*'()[]".indexOf(ch) !== -1
        || (ch === '!' && handle !== '!')) {
        end += 1;
      } else {
        if (start < end) chunks.push(chars.slice(start, end).join(''));
        start = end + 1;
        end = start;
        chunks.push(percentEncode(ch));
      }
    }
    if (start < end) chunks.push(chars.slice(start, end).join(''));
    const suffixText = chunks.join('');
    if (handle) return handle + suffixText;
    return '!<' + suffixText + '>';
  }

  prepareAnchor(anchor) {
    if (!anchor) throw new EmitterError('anchor must not be empty');
    for (const ch of anchor) {
      if (!((ch >= '0' && ch <= '9') || (ch >= 'A' && ch <= 'Z')
        || (ch >= 'a' && ch <= 'z') || ch === '-' || ch === '_')) {
        throw new EmitterError('invalid character ' + ch + ' in the anchor: ' + anchor);
      }
    }
    return anchor;
  }

  analyzeScalar(scalar) {
    if (!scalar) {
      return new ScalarAnalysis(scalar, true, false, false, true, true, true, false);
    }
    const chars = Array.from(scalar);
    const n = chars.length;
    let blockIndicators = false;
    let flowIndicators = false;
    let lineBreaks = false;
    let specialCharacters = false;
    let leadingSpace = false;
    let leadingBreak = false;
    let trailingSpace = false;
    let trailingBreak = false;
    let breakSpace = false;
    let spaceBreak = false;

    if (scalar.slice(0, 3) === '---' || scalar.slice(0, 3) === '...') {
      blockIndicators = true;
      flowIndicators = true;
    }

    let precededByWhitespace = true;
    let followedByWhitespace = n === 1 || isSpaceTabBreakNul(chars[1]);
    let previousSpace = false;
    let previousBreak = false;

    let index = 0;
    while (index < n) {
      const ch = chars[index];
      if (index === 0) {
        if ("#,[]{}&*!|>'\"%@`".indexOf(ch) !== -1) {
          flowIndicators = true;
          blockIndicators = true;
        }
        if (ch === '?' || ch === ':') {
          flowIndicators = true;
          if (followedByWhitespace) blockIndicators = true;
        }
        if (ch === '-' && followedByWhitespace) {
          flowIndicators = true;
          blockIndicators = true;
        }
      } else {
        if (',?[]{}'.indexOf(ch) !== -1) flowIndicators = true;
        if (ch === ':') {
          flowIndicators = true;
          if (followedByWhitespace) blockIndicators = true;
        }
        if (ch === '#' && precededByWhitespace) {
          flowIndicators = true;
          blockIndicators = true;
        }
      }

      if (isBreak(ch)) lineBreaks = true;
      if (!(ch === LF || (ch >= ' ' && ch <= '~'))) {
        const cp = ch.codePointAt(0);
        if ((cp === 0x85 || (cp >= 0xa0 && cp <= 0xd7ff)
          || (cp >= 0xe000 && cp <= 0xfffd)
          || (cp >= 0x10000 && cp < 0x10ffff)) && cp !== 0xfeff) {
          if (!this.allowUnicode) specialCharacters = true;
        } else {
          specialCharacters = true;
        }
      }

      if (ch === ' ') {
        if (index === 0) leadingSpace = true;
        if (index === n - 1) trailingSpace = true;
        if (previousBreak) breakSpace = true;
        previousSpace = true;
        previousBreak = false;
      } else if (isBreak(ch)) {
        if (index === 0) leadingBreak = true;
        if (index === n - 1) trailingBreak = true;
        if (previousSpace) spaceBreak = true;
        previousSpace = false;
        previousBreak = true;
      } else {
        previousSpace = false;
        previousBreak = false;
      }

      index += 1;
      precededByWhitespace = isSpaceTabBreakNul(ch);
      followedByWhitespace = index + 1 >= n || isSpaceTabBreakNul(chars[index + 1]);
    }

    let allowFlowPlain = true;
    let allowBlockPlain = true;
    let allowSingleQuoted = true;
    const allowDoubleQuoted = true;
    let allowBlock = true;

    if (leadingSpace || leadingBreak || trailingSpace || trailingBreak) {
      allowFlowPlain = false;
      allowBlockPlain = false;
    }
    if (trailingSpace) allowBlock = false;
    if (breakSpace) {
      allowFlowPlain = false;
      allowBlockPlain = false;
      allowSingleQuoted = false;
    }
    if (spaceBreak || specialCharacters) {
      allowFlowPlain = false;
      allowBlockPlain = false;
      allowSingleQuoted = false;
      allowBlock = false;
    }
    if (lineBreaks) {
      allowFlowPlain = false;
      allowBlockPlain = false;
    }
    if (flowIndicators) allowFlowPlain = false;
    if (blockIndicators) allowBlockPlain = false;

    return new ScalarAnalysis(scalar, false, lineBreaks, allowFlowPlain,
      allowBlockPlain, allowSingleQuoted, allowDoubleQuoted, allowBlock);
  }

  // -- writers ---------------------------------------------------------------

  write(data) {
    this.stream.push(data);
  }

  flushStream() {}

  writeStreamStart() {}

  writeStreamEnd() {
    this.flushStream();
  }

  writeIndicator(indicator, needWhitespace, whitespace = false, indention = false) {
    let data;
    if (this.whitespace || !needWhitespace) {
      data = indicator;
    } else {
      data = ' ' + indicator;
    }
    this.whitespace = whitespace;
    this.indention = this.indention && indention;
    this.column += Array.from(data).length;
    this.openEnded = false;
    this.write(data);
  }

  writeIndent() {
    const indent = this.indent || 0;
    if (!this.indention || this.column > indent
      || (this.column === indent && !this.whitespace)) {
      this.writeLineBreak();
    }
    if (this.column < indent) {
      this.whitespace = true;
      let data = '';
      for (let i = 0; i < indent - this.column; i += 1) data += ' ';
      this.column = indent;
      this.write(data);
    }
  }

  writeLineBreak(data) {
    const text = data === undefined || data === null ? this.bestLineBreak : data;
    this.whitespace = true;
    this.indention = true;
    this.line += 1;
    this.column = 0;
    this.write(text);
  }

  writeVersionDirective(versionText) {
    this.write('%YAML ' + versionText);
    this.writeLineBreak();
  }

  writeTagDirective(handleText, prefixText) {
    this.write('%TAG ' + handleText + ' ' + prefixText);
    this.writeLineBreak();
  }

  // -- scalar writers --------------------------------------------------------

  writeSingleQuoted(text, split = true) {
    this.writeIndicator("'", true, false, false);
    let spaces = false;
    let breaks = false;
    const chars = Array.from(text);
    const n = chars.length;
    let start = 0;
    let end = 0;
    while (end <= n) {
      let ch = null;
      if (end < n) ch = chars[end];
      if (spaces) {
        if (ch === null || ch !== ' ') {
          if (start + 1 === end && this.column > this.bestWidth && split
            && start !== 0 && end !== n) {
            this.writeIndent();
          } else {
            const data = chars.slice(start, end).join('');
            this.column += end - start;
            this.write(data);
          }
          start = end;
        }
      } else if (breaks) {
        if (ch === null || !isBreak(ch)) {
          if (chars[start] === LF) this.writeLineBreak();
          for (const br of chars.slice(start, end)) {
            if (br === LF) this.writeLineBreak();
            else this.writeLineBreak(br);
          }
          this.writeIndent();
          start = end;
        }
      } else if (ch === null || ch === ' ' || isBreak(ch) || ch === "'") {
        if (start < end) {
          const data = chars.slice(start, end).join('');
          this.column += end - start;
          this.write(data);
          start = end;
        }
      }
      if (ch === "'") {
        this.column += 2;
        this.write("''");
        start = end + 1;
      }
      if (ch !== null) {
        spaces = ch === ' ';
        breaks = isBreak(ch);
      }
      end += 1;
    }
    this.writeIndicator("'", false, false, false);
  }

  writeDoubleQuoted(text, split = true) {
    this.writeIndicator('"', true, false, false);
    const chars = Array.from(text);
    const n = chars.length;
    let start = 0;
    let end = 0;
    while (end <= n) {
      let ch = null;
      if (end < n) ch = chars[end];
      let mustEscape = ch === null;
      if (ch !== null) {
        const cp = ch.codePointAt(0);
        if (ch === '"' || ch === '\\' || cp === 0x85 || cp === 0x2028
          || cp === 0x2029 || cp === 0xfeff) {
          mustEscape = true;
        } else if (!((ch >= ' ' && ch <= '~')
          || (this.allowUnicode
            && ((cp >= 0xa0 && cp <= 0xd7ff) || (cp >= 0xe000 && cp <= 0xfffd))))) {
          mustEscape = true;
        }
      }
      if (mustEscape) {
        if (start < end) {
          const data = chars.slice(start, end).join('');
          this.column += end - start;
          this.write(data);
          start = end;
        }
        if (ch !== null) {
          let data;
          const cp = ch.codePointAt(0);
          if (ESCAPE_REPLACEMENTS.has(ch)) {
            data = '\\' + ESCAPE_REPLACEMENTS.get(ch);
          } else if (cp <= 0xff) {
            data = '\\x' + hexUpper(cp, 2);
          } else if (cp <= 0xffff) {
            data = '\\u' + hexUpper(cp, 4);
          } else {
            data = '\\U' + hexUpper(cp, 8);
          }
          this.column += data.length;
          this.write(data);
          start = end + 1;
        }
      }
      if (end > 0 && end < n - 1 && (ch === ' ' || start >= end)
        && this.column + (end - start) > this.bestWidth && split) {
        const data = chars.slice(start, end).join('') + '\\';
        if (start < end) start = end;
        this.column += Array.from(data).length;
        this.write(data);
        this.writeIndent();
        this.whitespace = false;
        this.indention = false;
        if (chars[start] === ' ') {
          this.column += 1;
          this.write('\\');
        }
      }
      end += 1;
    }
    this.writeIndicator('"', false, false, false);
  }

  determineBlockHints(text) {
    let hints = '';
    const chars = Array.from(text);
    if (chars.length) {
      const first = chars[0];
      if (first === ' ' || isBreak(first)) hints += String(this.bestIndent);
      const last = chars[chars.length - 1];
      if (!isBreak(last)) {
        hints += '-';
      } else if (chars.length === 1 || isBreak(chars[chars.length - 2])) {
        hints += '+';
      }
    }
    return hints;
  }

  writeFolded(text) {
    const hints = this.determineBlockHints(text);
    this.writeIndicator('>' + hints, true, false, false);
    if (hints.slice(-1) === '+') this.openEnded = true;
    this.writeLineBreak();
    let leadingSpace = true;
    let spaces = false;
    let breaks = true;
    const chars = Array.from(text);
    const n = chars.length;
    let start = 0;
    let end = 0;
    while (end <= n) {
      let ch = null;
      if (end < n) ch = chars[end];
      if (breaks) {
        if (ch === null || !isBreak(ch)) {
          if (!leadingSpace && ch !== null && ch !== ' ' && chars[start] === LF) {
            this.writeLineBreak();
          }
          leadingSpace = ch === ' ';
          for (const br of chars.slice(start, end)) {
            if (br === LF) this.writeLineBreak();
            else this.writeLineBreak(br);
          }
          if (ch !== null) this.writeIndent();
          start = end;
        }
      } else if (spaces) {
        if (ch !== ' ') {
          if (start + 1 === end && this.column > this.bestWidth) {
            this.writeIndent();
          } else {
            const data = chars.slice(start, end).join('');
            this.column += end - start;
            this.write(data);
          }
          start = end;
        }
      } else if (ch === null || ch === ' ' || isBreak(ch)) {
        const data = chars.slice(start, end).join('');
        this.column += end - start;
        this.write(data);
        if (ch === null) this.writeLineBreak();
        start = end;
      }
      if (ch !== null) {
        breaks = isBreak(ch);
        spaces = ch === ' ';
      }
      end += 1;
    }
  }

  writeLiteral(text) {
    const hints = this.determineBlockHints(text);
    this.writeIndicator('|' + hints, true, false, false);
    if (hints.slice(-1) === '+') this.openEnded = true;
    this.writeLineBreak();
    let breaks = true;
    const chars = Array.from(text);
    const n = chars.length;
    let start = 0;
    let end = 0;
    while (end <= n) {
      let ch = null;
      if (end < n) ch = chars[end];
      if (breaks) {
        if (ch === null || !isBreak(ch)) {
          for (const br of chars.slice(start, end)) {
            if (br === LF) this.writeLineBreak();
            else this.writeLineBreak(br);
          }
          if (ch !== null) this.writeIndent();
          start = end;
        }
      } else if (ch === null || isBreak(ch)) {
        const data = chars.slice(start, end).join('');
        this.write(data);
        if (ch === null) this.writeLineBreak();
        start = end;
      }
      if (ch !== null) breaks = isBreak(ch);
      end += 1;
    }
  }

  writePlain(text, split = true) {
    if (this.rootContext) this.openEnded = true;
    if (!text) return;
    if (!this.whitespace) {
      this.column += 1;
      this.write(' ');
    }
    this.whitespace = false;
    this.indention = false;
    let spaces = false;
    let breaks = false;
    const chars = Array.from(text);
    const n = chars.length;
    let start = 0;
    let end = 0;
    while (end <= n) {
      let ch = null;
      if (end < n) ch = chars[end];
      if (spaces) {
        if (ch !== ' ') {
          if (start + 1 === end && this.column > this.bestWidth && split) {
            this.writeIndent();
            this.whitespace = false;
            this.indention = false;
          } else {
            const data = chars.slice(start, end).join('');
            this.column += end - start;
            this.write(data);
          }
          start = end;
        }
      } else if (breaks) {
        if (ch === null || !isBreak(ch)) {
          if (chars[start] === LF) this.writeLineBreak();
          for (const br of chars.slice(start, end)) {
            if (br === LF) this.writeLineBreak();
            else this.writeLineBreak(br);
          }
          this.writeIndent();
          this.whitespace = false;
          this.indention = false;
          start = end;
        }
      } else if (ch === null || ch === ' ' || isBreak(ch)) {
        const data = chars.slice(start, end).join('');
        this.column += end - start;
        this.write(data);
        start = end;
      }
      if (ch !== null) {
        spaces = ch === ' ';
        breaks = isBreak(ch);
      }
      end += 1;
    }
  }
}

function percentEncode(ch) {
  let out = '';
  const bytes = [];
  const cp = ch.codePointAt(0);
  if (cp < 0x80) {
    bytes.push(cp);
  } else if (cp < 0x800) {
    bytes.push(0xc0 | (cp >> 6), 0x80 | (cp & 0x3f));
  } else if (cp < 0x10000) {
    bytes.push(0xe0 | (cp >> 12), 0x80 | ((cp >> 6) & 0x3f), 0x80 | (cp & 0x3f));
  } else {
    bytes.push(0xf0 | (cp >> 18), 0x80 | ((cp >> 12) & 0x3f),
      0x80 | ((cp >> 6) & 0x3f), 0x80 | (cp & 0x3f));
  }
  for (const b of bytes) out += '%' + hexUpper(b, 2);
  return out;
}

export { ScalarAnalysis };

toolUseResult.content:
// The Emitter: turns events into text.  A faithful port of PyYAML's emitter.py.
// All text is handled as arrays of code points so that lengths and columns
// match Python's string indices exactly.

import { CR, LF, LINE_BREAKS, NUL, SPACE, TAB } from './chars.mjs';
import { EmitterError } from './errors.mjs';
import {
  AliasEvent, CollectionEndEvent, CollectionStartEvent, DocumentEndEvent,
  DocumentStartEvent, MappingStartEvent, NodeEvent, ScalarEvent,
  SequenceEndEvent, MappingEndEvent, SequenceStartEvent, StreamEndEvent,
  StreamStartEvent,
} from './events.mjs';

const NULL_BL_T_LINEBR = NUL + SPACE + TAB + CR + LINE_BREAKS;

function isBreak(ch) {
  return ch === LF || LINE_BREAKS.indexOf(ch) !== -1;
}

function isSpaceTabBreakNul(ch) {
  return NULL_BL_T_LINEBR.indexOf(ch) !== -1;
}

const DEFAULT_TAG_PREFIXES = { '!': '!', 'tag:yaml.org,2002:': '!!' };

const ESCAPE_REPLACEMENTS = new Map([
  [String.fromCharCode(0x00), '0'],
  [String.fromCharCode(0x07), 'a'],
  [String.fromCharCode(0x08), 'b'],
  [String.fromCharCode(0x09), 't'],
  [String.fromCharCode(0x0a), 'n'],
  [String.fromCharCode(0x0b), 'v'],
  [String.fromCharCode(0x0c), 'f'],
  [String.fromCharCode(0x0d), 'r'],
  [String.fromCharCode(0x1b), 'e'],
  ['"', '"'],
  ['\\', '\\'],
  [String.fromCharCode(0x85), 'N'],
  [String.fromCharCode(0xa0), '_'],
  [String.fromCharCode(0x2028), 'L'],
  [String.fromCharCode(0x2029), 'P'],
]);

class ScalarAnalysis {
  constructor(scalar, empty, multiline, allowFlowPlain, allowBlockPlain,
    allowSingleQuoted, allowDoubleQuoted, allowBlock) {
    this.scalar = scalar;
    this.empty = empty;
    this.multiline = multiline;
    this.allowFlowPlain = allowFlowPlain;
    this.allowBlockPlain = allowBlockPlain;
    this.allowSingleQuoted = allowSingleQuoted;
    this.allowDoubleQuoted = allowDoubleQuoted;
    this.allowBlock = allowBlock;
  }
}

function hexUpper(cp, width) {
  let hex = cp.toString(16).toUpperCase();
  while (hex.length < width) hex = '0' + hex;
  return hex;
}

export class Emitter {
  constructor(stream, options = {}) {
    this.stream = stream;
    this.encoding = null;
    this.states = [];
    this.state = 'expectStreamStart';
    this.events = [];
    this.event = null;
    this.indents = [];
    this.indent = null;
    this.flowLevel = 0;
    this.rootContext = false;
    this.sequenceContext = false;
    this.mappingContext = false;
    this.simpleKeyContext = false;
    this.line = 0;
    this.column = 0;
    this.whitespace = true;
    this.indention = true;
    this.openEnded = false;
    this.canonical = options.canonical || null;
    this.allowUnicode = options.allowUnicode === undefined ? null : options.allowUnicode;
    this.bestIndent = 2;
    if (options.indent && options.indent > 1 && options.indent < 10) {
      this.bestIndent = options.indent;
    }
    this.bestWidth = 80;
    if (options.width && options.width > this.bestIndent * 2) {
      this.bestWidth = options.width;
    }
    this.bestLineBreak = LF;
    if (options.lineBreak === CR || options.lineBreak === LF
      || options.lineBreak === CR + LF) {
      this.bestLineBreak = options.lineBreak;
    }
    this.tagPrefixes = null;
    this.preparedAnchor = null;
    this.preparedTag = null;
    this.analysis = null;
    this.style = null;
  }

  emit(event) {
    this.events.push(event);
    while (!this.needMoreEvents()) {
      this.event = this.events.shift();
      this[this.state]();
      this.event = null;
    }
  }

  needMoreEvents() {
    if (!this.events.length) return true;
    const event = this.events[0];
    if (event instanceof DocumentStartEvent) return this.needEvents(1);
    if (event instanceof SequenceStartEvent) return this.needEvents(2);
    if (event instanceof MappingStartEvent) return this.needEvents(3);
    return false;
  }

  needEvents(count) {
    let level = 0;
    for (let i = 1; i < this.events.length; i += 1) {
      const event = this.events[i];
      if (event instanceof DocumentStartEvent || event instanceof CollectionStartEvent) {
        level += 1;
      } else if (event instanceof DocumentEndEvent
        || event instanceof CollectionEndEvent) {
        level -= 1;
      } else if (event instanceof StreamEndEvent) {
        level = -1;
      }
      if (level < 0) return false;
    }
    return this.events.length < count + 1;
  }

  increaseIndent(flow = false, indentless = false) {
    this.indents.push(this.indent);
    if (this.indent === null) {
      this.indent = flow ? this.bestIndent : 0;
    } else if (!indentless) {
      this.indent += this.bestIndent;
    }
  }

  // -- states ----------------------------------------------------------------

  expectStreamStart() {
    if (this.event instanceof StreamStartEvent) {
      this.writeStreamStart();
      this.state = 'expectFirstDocumentStart';
    } else {
      throw new EmitterError('expected StreamStartEvent, but got ' + this.event);
    }
  }

  expectNothing() {
    throw new EmitterError('expected nothing, but got ' + this.event);
  }

  expectFirstDocumentStart() {
    return this.expectDocumentStart(true);
  }

  expectDocumentStartState() {
    return this.expectDocumentStart(false);
  }

  expectDocumentStart(first = false) {
    if (this.event instanceof DocumentStartEvent) {
      if ((this.event.version || this.event.tags) && this.openEnded) {
        this.writeIndicator('...', true);
        this.writeIndent();
      }
      if (this.event.version) {
        this.writeVersionDirective(this.prepareVersion(this.event.version));
      }
      this.tagPrefixes = Object.assign({}, DEFAULT_TAG_PREFIXES);
      if (this.event.tags) {
        const handles = Object.keys(this.event.tags).sort();
        for (const handle of handles) {
          const prefix = this.event.tags[handle];
          this.tagPrefixes[prefix] = handle;
          this.writeTagDirective(this.prepareTagHandle(handle),
            this.prepareTagPrefix(prefix));
        }
      }
      const implicit = first && !this.event.explicit && !this.canonical
        && !this.event.version && !this.event.tags && !this.checkEmptyDocument();
      if (!implicit) {
        this.writeIndent();
        this.writeIndicator('---', true);
        if (this.canonical) this.writeIndent();
      }
      this.state = 'expectDocumentRoot';
    } else if (this.event instanceof StreamEndEvent) {
      if (this.openEnded) {
        this.writeIndicator('...', true);
        this.writeIndent();
      }
      this.writeStreamEnd();
      this.state = 'expectNothing';
    } else {
      throw new EmitterError('expected DocumentStartEvent, but got ' + this.event);
    }
    return undefined;
  }

  expectDocumentEnd() {
    if (this.event instanceof DocumentEndEvent) {
      this.writeIndent();
      if (this.event.explicit) {
        this.writeIndicator('...', true);
        this.writeIndent();
      }
      this.flushStream();
      this.state = 'expectDocumentStartState';
    } else {
      throw new EmitterError('expected DocumentEndEvent, but got ' + this.event);
    }
  }

  expectDocumentRoot() {
    this.states.push('expectDocumentEnd');
    this.expectNode(true, false, false, false);
  }

  expectNode(root = false, sequence = false, mapping = false, simpleKey = false) {
    this.rootContext = root;
    this.sequenceContext = sequence;
    this.mappingContext = mapping;
    this.simpleKeyContext = simpleKey;
    if (this.event instanceof AliasEvent) {
      this.expectAlias();
    } else if (this.event instanceof ScalarEvent
      || this.event instanceof CollectionStartEvent) {
      this.processAnchor('&');
      this.processTag();
      if (this.event instanceof ScalarEvent) {
        this.expectScalar();
      } else if (this.event instanceof SequenceStartEvent) {
        if (this.flowLevel || this.canonical || this.event.flowStyle
          || this.checkEmptySequence()) {
          this.expectFlowSequence();
        } else {
          this.expectBlockSequence();
        }
      } else if (this.event instanceof MappingStartEvent) {
        if (this.flowLevel || this.canonical || this.event.flowStyle
          || this.checkEmptyMapping()) {
          this.expectFlowMapping();
        } else {
          this.expectBlockMapping();
        }
      }
    } else {
      throw new EmitterError('expected NodeEvent, but got ' + this.event);
    }
  }

  expectAlias() {
    if (this.event.anchor === null) {
      throw new EmitterError('anchor is not specified for alias');
    }
    this.processAnchor('*');
    this.state = this.states.pop();
  }

  expectScalar() {
    this.increaseIndent(true, false);
    this.processScalar();
    this.indent = this.indents.pop();
    this.state = this.states.pop();
  }

  // -- flow sequence ---------------------------------------------------------

  expectFlowSequence() {
    this.writeIndicator('[', true, true, false);
    this.flowLevel += 1;
    this.increaseIndent(true, false);
    this.state = 'expectFirstFlowSequenceItem';
  }

  expectFirstFlowSequenceItem() {
    if (this.event instanceof SequenceEndEvent) {
      this.indent = this.indents.pop();
      this.flowLevel -= 1;
      this.writeIndicator(']', false, false, false);
      this.state = this.states.pop();
    } else {
      if (this.canonical || this.column > this.bestWidth) this.writeIndent();
      this.states.push('expectFlowSequenceItem');
      this.expectNode(false, true, false, false);
    }
  }

  expectFlowSequenceItem() {
    if (this.event instanceof SequenceEndEvent) {
      this.indent = this.indents.pop();
      this.flowLevel -= 1;
      if (this.canonical) {
        this.writeIndicator(',', false, false, false);
        this.writeIndent();
      }
      this.writeIndicator(']', false, false, false);
      this.state = this.states.pop();
    } else {
      this.writeIndicator(',', false, false, false);
      if (this.canonical || this.column > this.bestWidth) this.writeIndent();
      this.states.push('expectFlowSequenceItem');
      this.expectNode(false, true, false, false);
    }
  }

  // -- flow mapping ----------------------------------------------------------

  expectFlowMapping() {
    this.writeIndicator('{', true, true, false);
    this.flowLevel += 1;
    this.increaseIndent(true, false);
    this.state = 'expectFirstFlowMappingKey';
  }

  expectFirstFlowMappingKey() {
    if (this.event instanceof MappingEndEvent) {
      this.indent = this.indents.pop();
      this.flowLevel -= 1;
      this.writeIndicator('}', false, false, false);
      this.state = this.states.pop();
    } else {
      if (this.canonical || this.column > this.bestWidth) this.writeIndent();
      if (!this.canonical && this.checkSimpleKey()) {
        this.states.push('expectFlowMappingSimpleValue');
        this.expectNode(false, false, true, true);
      } else {
        this.writeIndicator('?', true, false, false);
        this.states.push('expectFlowMappingValue');
        this.expectNode(false, false, true, false);
      }
    }
  }

  expectFlowMappingKey() {
    if (this.event instanceof MappingEndEvent) {
      this.indent = this.indents.pop();
      this.flowLevel -= 1;
      if (this.canonical) {
        this.writeIndicator(',', false, false, false);
        this.writeIndent();
      }
      this.writeIndicator('}', false, false, false);
      this.state = this.states.pop();
    } else {
      this.writeIndicator(',', false, false, false);
      if (this.canonical || this.column > this.bestWidth) this.writeIndent();
      if (!this.canonical && this.checkSimpleKey()) {
        this.states.push('expectFlowMappingSimpleValue');
        this.expectNode(false, false, true, true);
      } else {
        this.writeIndicator('?', true, false, false);
        this.states.push('expectFlowMappingValue');
        this.expectNode(false, false, true, false);
      }
    }
  }

  expectFlowMappingSimpleValue() {
    this.writeIndicator(':', false, false, false);
    this.states.push('expectFlowMappingKey');
    this.expectNode(false, false, true, false);
  }

  expectFlowMappingValue() {
    if (this.canonical || this.column > this.bestWidth) this.writeIndent();
    this.writeIndicator(':', true, false, false);
    this.states.push('expectFlowMappingKey');
    this.expectNode(false, false, true, false);
  }

  // -- block sequence --------------------------------------------------------

  expectBlockSequence() {
    const indentless = this.mappingContext && !this.indention;
    this.increaseIndent(false, indentless);
    this.state = 'expectFirstBlockSequenceItem';
  }

  expectFirstBlockSequenceItem() {
    return this.expectBlockSequenceItem(true);
  }

  expectBlockSequenceItemState() {
    return this.expectBlockSequenceItem(false);
  }

  expectBlockSequenceItem(first = false) {
    if (!first && this.event instanceof SequenceEndEvent) {
      this.indent = this.indents.pop();
      this.state = this.states.pop();
    } else {
      this.writeIndent();
      this.writeIndicator('-', true, false, true);
      this.states.push('expectBlockSequenceItemState');
      this.expectNode(false, true, false, false);
    }
    return undefined;
  }

  // -- block mapping ---------------------------------------------------------

  expectBlockMapping() {
    this.increaseIndent(false, false);
    this.state = 'expectFirstBlockMappingKey';
  }

  expectFirstBlockMappingKey() {
    return this.expectBlockMappingKey(true);
  }

  expectBlockMappingKeyState() {
    return this.expectBlockMappingKey(false);
  }

  expectBlockMappingKey(first = false) {
    if (!first && this.event instanceof MappingEndEvent) {
      this.indent = this.indents.pop();
      this.state = this.states.pop();
    } else {
      this.writeIndent();
      if (this.checkSimpleKey()) {
        this.states.push('expectBlockMappingSimpleValue');
        this.expectNode(false, false, true, true);
      } else {
        this.writeIndicator('?', true, false, true);
        this.states.push('expectBlockMappingValue');
        this.expectNode(false, false, true, false);
      }
    }
    return undefined;
  }

  expectBlockMappingSimpleValue() {
    this.writeIndicator(':', false, false, false);
    this.states.push('expectBlockMappingKeyState');
    this.expectNode(false, false, true, false);
  }

  expectBlockMappingValue() {
    this.writeIndent();
    this.writeIndicator(':', true, false, true);
    this.states.push('expectBlockMappingKeyState');
    this.expectNode(false, false, true, false);
  }

  // -- checkers --------------------------------------------------------------

  checkEmptySequence() {
    return this.event instanceof SequenceStartEvent && this.events.length
      && this.events[0] instanceof SequenceEndEvent;
  }

  checkEmptyMapping() {
    return this.event instanceof MappingStartEvent && this.events.length
      && this.events[0] instanceof MappingEndEvent;
  }

  checkEmptyDocument() {
    if (!(this.event instanceof DocumentStartEvent) || !this.events.length) {
      return false;
    }
    const event = this.events[0];
    return event instanceof ScalarEvent && event.anchor === null
      && event.tag === null && event.implicit && event.value === '';
  }

  checkSimpleKey() {
    let length = 0;
    if (this.event instanceof NodeEvent && this.event.anchor !== null) {
      if (this.preparedAnchor === null) {
        this.preparedAnchor = this.prepareAnchor(this.event.anchor);
      }
      length += Array.from(this.preparedAnchor).length;
    }
    if ((this.event instanceof ScalarEvent || this.event instanceof CollectionStartEvent)
      && this.event.tag !== null) {
      if (this.preparedTag === null) {
        this.preparedTag = this.prepareTag(this.event.tag);
      }
      length += Array.from(this.preparedTag).length;
    }
    if (this.event instanceof ScalarEvent) {
      if (this.analysis === null) this.analysis = this.analyzeScalar(this.event.value);
      length += Array.from(this.analysis.scalar).length;
    }
    return length < 128 && (this.event instanceof AliasEvent
      || (this.event instanceof ScalarEvent
        && !this.analysis.empty && !this.analysis.multiline)
      || this.checkEmptySequence() || this.checkEmptyMapping());
  }

  // -- anchor, tag and scalar processors -------------------------------------

  processAnchor(indicator) {
    if (this.event.anchor === null) {
      this.preparedAnchor = null;
      return;
    }
    if (this.preparedAnchor === null) {
      this.preparedAnchor = this.prepareAnchor(this.event.anchor);
    }
    if (this.preparedAnchor) {
      this.writeIndicator(indicator + this.preparedAnchor, true, false, false);
    }
    this.preparedAnchor = null;
  }

  processTag() {
    let tag = this.event.tag;
    if (this.event instanceof ScalarEvent) {
      if (this.style === null) this.style = this.chooseScalarStyle();
      if ((!this.canonical || tag === null)
        && ((this.style === '' && this.event.implicit[0])
          || (this.style !== '' && this.event.implicit[1]))) {
        this.preparedTag = null;
        return;
      }
      if (this.event.implicit[0] && tag === null) {
        tag = '!';
        this.preparedTag = null;
      }
    } else if ((!this.canonical || tag === null) && this.event.implicit) {
      this.preparedTag = null;
      return;
    }
    if (tag === null) throw new EmitterError('tag is not specified');
    if (this.preparedTag === null) this.preparedTag = this.prepareTag(tag);
    if (this.preparedTag) {
      this.writeIndicator(this.preparedTag, true, false, false);
    }
    this.preparedTag = null;
  }

  chooseScalarStyle() {
    if (this.analysis === null) this.analysis = this.analyzeScalar(this.event.value);
    if (this.event.style === '"' || this.canonical) return '"';
    if (!this.event.style && this.event.implicit[0]) {
      if (!(this.simpleKeyContext && (this.analysis.empty || this.analysis.multiline))
        && ((this.flowLevel && this.analysis.allowFlowPlain)
          || (!this.flowLevel && this.analysis.allowBlockPlain))) {
        return '';
      }
    }
    if (this.event.style && (this.event.style === '|' || this.event.style === '>')) {
      if (!this.flowLevel && !this.simpleKeyContext && this.analysis.allowBlock) {
        return this.event.style;
      }
    }
    if (!this.event.style || this.event.style === "'") {
      if (this.analysis.allowSingleQuoted
        && !(this.simpleKeyContext && this.analysis.multiline)) {
        return "'";
      }
    }
    return '"';
  }

  processScalar() {
    if (this.analysis === null) this.analysis = this.analyzeScalar(this.event.value);
    if (this.style === null) this.style = this.chooseScalarStyle();
    const split = !this.simpleKeyContext;
    if (this.style === '"') {
      this.writeDoubleQuoted(this.analysis.scalar, split);
    } else if (this.style === "'") {
      this.writeSingleQuoted(this.analysis.scalar, split);
    } else if (this.style === '>') {
      this.writeFolded(this.analysis.scalar);
    } else if (this.style === '|') {
      this.writeLiteral(this.analysis.scalar);
    } else {
      this.writePlain(this.analysis.scalar, split);
    }
    this.analysis = null;
    this.style = null;
  }

  // -- analyzers -------------------------------------------------------------

  prepareVersion(version) {
    const [major, minor] = version;
    if (major !== 1) {
      throw new EmitterError('unsupported YAML version: ' + major + '.' + minor);
    }
    return major + '.' + minor;
  }

  prepareTagHandle(handle) {
    if (!handle) throw new EmitterError('tag handle must not be empty');
    if (handle.charAt(0) !== '!' || handle.charAt(handle.length - 1) !== '!') {
      throw new EmitterError("tag handle must start and end with '!': " + handle);
    }
    for (const ch of handle.slice(1, -1)) {
      if (!((ch >= '0' && ch <= '9') || (ch >= 'A' && ch <= 'Z')
        || (ch >= 'a' && ch <= 'z') || ch === '-' || ch === '_')) {
        throw new EmitterError('invalid character ' + ch + ' in the tag handle: ' + handle);
      }
    }
    return handle;
  }

  prepareTagPrefix(prefix) {
    if (!prefix) throw new EmitterError('tag prefix must not be empty');
    const chunks = [];
    let start = 0;
    let end = 0;
    const chars = Array.from(prefix);
    if (chars[0] === '!') end = 1;
    while (end < chars.length) {
      const ch = chars[end];
      if ((ch >= '0' && ch <= '9') || (ch >= 'A' && ch <= 'Z')
        || (ch >= 'a' && ch <= 'z') || "-;/?!:@&=+$,_.~*'()[]".indexOf(ch) !== -1) {
        end += 1;
      } else {
        if (start < end) chunks.push(chars.slice(start, end).join(''));
        start = end + 1;
        end = start;
        chunks.push(percentEncode(ch));
      }
    }
    if (start < end) chunks.push(chars.slice(start, end).join(''));
    return chunks.join('');
  }

  prepareTag(tag) {
    if (!tag) throw new EmitterError('tag must not be empty');
    if (tag === '!') return tag;
    let handle = null;
    let suffix = tag;
    const prefixes = Object.keys(this.tagPrefixes).sort();
    for (const prefix of prefixes) {
      if (tag.slice(0, prefix.length) === prefix
        && (prefix === '!' || prefix.length < tag.length)) {
        handle = this.tagPrefixes[prefix];
        suffix = tag.slice(prefix.length);
      }
    }
    const chunks = [];
    const chars = Array.from(suffix);
    let start = 0;
    let end = 0;
    while (end < chars.length) {
      const ch = chars[end];
      if ((ch >= '0' && ch <= '9') || (ch >= 'A' && ch <= 'Z')
        || (ch >= 'a' && ch <= 'z') || "-;/?:@&=+$,_.~*'()[]".indexOf(ch) !== -1
        || (ch === '!' && handle !== '!')) {
        end += 1;
      } else {
        if (start < end) chunks.push(chars.slice(start, end).join(''));
        start = end + 1;
        end = start;
        chunks.push(percentEncode(ch));
      }
    }
    if (start < end) chunks.push(chars.slice(start, end).join(''));
    const suffixText = chunks.join('');
    if (handle) return handle + suffixText;
    return '!<' + suffixText + '>';
  }

  prepareAnchor(anchor) {
    if (!anchor) throw new EmitterError('anchor must not be empty');
    for (const ch of anchor) {
      if (!((ch >= '0' && ch <= '9') || (ch >= 'A' && ch <= 'Z')
        || (ch >= 'a' && ch <= 'z') || ch === '-' || ch === '_')) {
        throw new EmitterError('invalid character ' + ch + ' in the anchor: ' + anchor);
      }
    }
    return anchor;
  }

  analyzeScalar(scalar) {
    if (!scalar) {
      return new ScalarAnalysis(scalar, true, false, false, true, true, true, false);
    }
    const chars = Array.from(scalar);
    const n = chars.length;
    let blockIndicators = false;
    let flowIndicators = false;
    let lineBreaks = false;
    let specialCharacters = false;
    let leadingSpace = false;
    let leadingBreak = false;
    let trailingSpace = false;
    let trailingBreak = false;
    let breakSpace = false;
    let spaceBreak = false;

    if (scalar.slice(0, 3) === '---' || scalar.slice(0, 3) === '...') {
      blockIndicators = true;
      flowIndicators = true;
    }

    let precededByWhitespace = true;
    let followedByWhitespace = n === 1 || isSpaceTabBreakNul(chars[1]);
    let previousSpace = false;
    let previousBreak = false;

    let index = 0;
    while (index < n) {
      const ch = chars[index];
      if (index === 0) {
        if ("#,[]{}&*!|>'\"%@`".indexOf(ch) !== -1) {
          flowIndicators = true;
          blockIndicators = true;
        }
        if (ch === '?' || ch === ':') {
          flowIndicators = true;
          if (followedByWhitespace) blockIndicators = true;
        }
        if (ch === '-' && followedByWhitespace) {
          flowIndicators = true;
          blockIndicators = true;
        }
      } else {
        if (',?[]{}'.indexOf(ch) !== -1) flowIndicators = true;
        if (ch === ':') {
          flowIndicators = true;
          if (followedByWhitespace) blockIndicators = true;
        }
        if (ch === '#' && precededByWhitespace) {
          flowIndicators = true;
          blockIndicators = true;
        }
      }

      if (isBreak(ch)) lineBreaks = true;
      if (!(ch === LF || (ch >= ' ' && ch <= '~'))) {
        const cp = ch.codePointAt(0);
        if ((cp === 0x85 || (cp >= 0xa0 && cp <= 0xd7ff)
          || (cp >= 0xe000 && cp <= 0xfffd)
          || (cp >= 0x10000 && cp < 0x10ffff)) && cp !== 0xfeff) {
          if (!this.allowUnicode) specialCharacters = true;
        } else {
          specialCharacters = true;
        }
      }

      if (ch === ' ') {
        if (index === 0) leadingSpace = true;
        if (index === n - 1) trailingSpace = true;
        if (previousBreak) breakSpace = true;
        previousSpace = true;
        previousBreak = false;
      } else if (isBreak(ch)) {
        if (index === 0) leadingBreak = true;
        if (index === n - 1) trailingBreak = true;
        if (previousSpace) spaceBreak = true;
        previousSpace = false;
        previousBreak = true;
      } else {
        previousSpace = false;
        previousBreak = false;
      }

      index += 1;
      precededByWhitespace = isSpaceTabBreakNul(ch);
      followedByWhitespace = index + 1 >= n || isSpaceTabBreakNul(chars[index + 1]);
    }

    let allowFlowPlain = true;
    let allowBlockPlain = true;
    let allowSingleQuoted = true;
    const allowDoubleQuoted = true;
    let allowBlock = true;

    if (leadingSpace || leadingBreak || trailingSpace || trailingBreak) {
      allowFlowPlain = false;
      allowBlockPlain = false;
    }
    if (trailingSpace) allowBlock = false;
    if (breakSpace) {
      allowFlowPlain = false;
      allowBlockPlain = false;
      allowSingleQuoted = false;
    }
    if (spaceBreak || specialCharacters) {
      allowFlowPlain = false;
      allowBlockPlain = false;
      allowSingleQuoted = false;
      allowBlock = false;
    }
    if (lineBreaks) {
      allowFlowPlain = false;
      allowBlockPlain = false;
    }
    if (flowIndicators) allowFlowPlain = false;
    if (blockIndicators) allowBlockPlain = false;

    return new ScalarAnalysis(scalar, false, lineBreaks, allowFlowPlain,
      allowBlockPlain, allowSingleQuoted, allowDoubleQuoted, allowBlock);
  }

  // -- writers ---------------------------------------------------------------

  write(data) {
    this.stream.push(data);
  }

  flushStream() {}

  writeStreamStart() {}

  writeStreamEnd() {
    this.flushStream();
  }

  writeIndicator(indicator, needWhitespace, whitespace = false, indention = false) {
    let data;
    if (this.whitespace || !needWhitespace) {
      data = indicator;
    } else {
      data = ' ' + indicator;
    }
    this.whitespace = whitespace;
    this.indention = this.indention && indention;
    this.column += Array.from(data).length;
    this.openEnded = false;
    this.write(data);
  }

  writeIndent() {
    const indent = this.indent || 0;
    if (!this.indention || this.column > indent
      || (this.column === indent && !this.whitespace)) {
      this.writeLineBreak();
    }
    if (this.column < indent) {
      this.whitespace = true;
      let data = '';
      for (let i = 0; i < indent - this.column; i += 1) data += ' ';
      this.column = indent;
      this.write(data);
    }
  }

  writeLineBreak(data) {
    const text = data === undefined || data === null ? this.bestLineBreak : data;
    this.whitespace = true;
    this.indention = true;
    this.line += 1;
    this.column = 0;
    this.write(text);
  }

  writeVersionDirective(versionText) {
    this.write('%YAML ' + versionText);
    this.writeLineBreak();
  }

  writeTagDirective(handleText, prefixText) {
    this.write('%TAG ' + handleText + ' ' + prefixText);
    this.writeLineBreak();
  }

  // -- scalar writers --------------------------------------------------------

  writeSingleQuoted(text, split = true) {
    this.writeIndicator("'", true, false, false);
    let spaces = false;
    let breaks = false;
    const chars = Array.from(text);
    const n = chars.length;
    let start = 0;
    let end = 0;
    while (end <= n) {
      let ch = null;
      if (end < n) ch = chars[end];
      if (spaces) {
        if (ch === null || ch !== ' ') {
          if (start + 1 === end && this.column > this.bestWidth && split
            && start !== 0 && end !== n) {
            this.writeIndent();
          } else {
            const data = chars.slice(start, end).join('');
            this.column += end - start;
            this.write(data);
          }
          start = end;
        }
      } else if (breaks) {
        if (ch === null || !isBreak(ch)) {
          if (chars[start] === LF) this.writeLineBreak();
          for (const br of chars.slice(start, end)) {
            if (br === LF) this.writeLineBreak();
            else this.writeLineBreak(br);
          }
          this.writeIndent();
          start = end;
        }
      } else if (ch === null || ch === ' ' || isBreak(ch) || ch === "'") {
        if (start < end) {
          const data = chars.slice(start, end).join('');
          this.column += end - start;
          this.write(data);
          start = end;
        }
      }
      if (ch === "'") {
        this.column += 2;
        this.write("''");
        start = end + 1;
      }
      if (ch !== null) {
        spaces = ch === ' ';
        breaks = isBreak(ch);
      }
      end += 1;
    }
    this.writeIndicator("'", false, false, false);
  }

  writeDoubleQuoted(text, split = true) {
    this.writeIndicator('"', true, false, false);
    const chars = Array.from(text);
    const n = chars.length;
    let start = 0;
    let end = 0;
    while (end <= n) {
      let ch = null;
      if (end < n) ch = chars[end];
      let mustEscape = ch === null;
      if (ch !== null) {
        const cp = ch.codePointAt(0);
        if (ch === '"' || ch === '\\' || cp === 0x85 || cp === 0x2028
          || cp === 0x2029 || cp === 0xfeff) {
          mustEscape = true;
        } else if (!((ch >= ' ' && ch <= '~')
          || (this.allowUnicode
            && ((cp >= 0xa0 && cp <= 0xd7ff) || (cp >= 0xe000 && cp <= 0xfffd))))) {
          mustEscape = true;
        }
      }
      if (mustEscape) {
        if (start < end) {
          const data = chars.slice(start, end).join('');
          this.column += end - start;
          this.write(data);
          start = end;
        }
        if (ch !== null) {
          let data;
          const cp = ch.codePointAt(0);
          if (ESCAPE_REPLACEMENTS.has(ch)) {
            data = '\\' + ESCAPE_REPLACEMENTS.get(ch);
          } else if (cp <= 0xff) {
            data = '\\x' + hexUpper(cp, 2);
          } else if (cp <= 0xffff) {
            data = '\\u' + hexUpper(cp, 4);
          } else {
            data = '\\U' + hexUpper(cp, 8);
          }
          this.column += data.length;
          this.write(data);
          start = end + 1;
        }
      }
      if (end > 0 && end < n - 1 && (ch === ' ' || start >= end)
        && this.column + (end - start) > this.bestWidth && split) {
        const data = chars.slice(start, end).join('') + '\\';
        if (start < end) start = end;
        this.column += Array.from(data).length;
        this.write(data);
        this.writeIndent();
        this.whitespace = false;
        this.indention = false;
        if (chars[start] === ' ') {
          this.column += 1;
          this.write('\\');
        }
      }
      end += 1;
    }
    this.writeIndicator('"', false, false, false);
  }

  determineBlockHints(text) {
    let hints = '';
    const chars = Array.from(text);
    if (chars.length) {
      const first = chars[0];
      if (first === ' ' || isBreak(first)) hints += String(this.bestIndent);
      const last = chars[chars.length - 1];
      if (!isBreak(last)) {
        hints += '-';
      } else if (chars.length === 1 || isBreak(chars[chars.length - 2])) {
        hints += '+';
      }
    }
    return hints;
  }

  writeFolded(text) {
    const hints = this.determineBlockHints(text);
    this.writeIndicator('>' + hints, true, false, false);
    if (hints.slice(-1) === '+') this.openEnded = true;
    this.writeLineBreak();
    let leadingSpace = true;
    let spaces = false;
    let breaks = true;
    const chars = Array.from(text);
    const n = chars.length;
    let start = 0;
    let end = 0;
    while (end <= n) {
      let ch = null;
      if (end < n) ch = chars[end];
      if (breaks) {
        if (ch === null || !isBreak(ch)) {
          if (!leadingSpace && ch !== null && ch !== ' ' && chars[start] === LF) {
            this.writeLineBreak();
          }
          leadingSpace = ch === ' ';
          for (const br of chars.slice(start, end)) {
            if (br === LF) this.writeLineBreak();
            else this.writeLineBreak(br);
          }
          if (ch !== null) this.writeIndent();
          start = end;
        }
      } else if (spaces) {
        if (ch !== ' ') {
          if (start + 1 === end && this.column > this.bestWidth) {
            this.writeIndent();
          } else {
            const data = chars.slice(start, end).join('');
            this.column += end - start;
            this.write(data);
          }
          start = end;
        }
      } else if (ch === null || ch === ' ' || isBreak(ch)) {
        const data = chars.slice(start, end).join('');
        this.column += end - start;
        this.write(data);
        if (ch === null) this.writeLineBreak();
        start = end;
      }
      if (ch !== null) {
        breaks = isBreak(ch);
        spaces = ch === ' ';
      }
      end += 1;
    }
  }

  writeLiteral(text) {
    const hints = this.determineBlockHints(text);
    this.writeIndicator('|' + hints, true, false, false);
    if (hints.slice(-1) === '+') this.openEnded = true;
    this.writeLineBreak();
    let breaks = true;
    const chars = Array.from(text);
    const n = chars.length;
    let start = 0;
    let end = 0;
    while (end <= n) {
      let ch = null;
      if (end < n) ch = chars[end];
      if (breaks) {
        if (ch === null || !isBreak(ch)) {
          for (const br of chars.slice(start, end)) {
            if (br === LF) this.writeLineBreak();
            else this.writeLineBreak(br);
          }
          if (ch !== null) this.writeIndent();
          start = end;
        }
      } else if (ch === null || isBreak(ch)) {
        const data = chars.slice(start, end).join('');
        this.write(data);
        if (ch === null) this.writeLineBreak();
        start = end;
      }
      if (ch !== null) breaks = isBreak(ch);
      end += 1;
    }
  }

  writePlain(text, split = true) {
    if (this.rootContext) this.openEnded = true;
    if (!text) return;
    if (!this.whitespace) {
      this.column += 1;
      this.write(' ');
    }
    this.whitespace = false;
    this.indention = false;
    let spaces = false;
    let breaks = false;
    const chars = Array.from(text);
    const n = chars.length;
    let start = 0;
    let end = 0;
    while (end <= n) {
      let ch = null;
      if (end < n) ch = chars[end];
      if (spaces) {
        if (ch !== ' ') {
          if (start + 1 === end && this.column > this.bestWidth && split) {
            this.writeIndent();
            this.whitespace = false;
            this.indention = false;
          } else {
            const data = chars.slice(start, end).join('');
            this.column += end - start;
            this.write(data);
          }
          start = end;
        }
      } else if (breaks) {
        if (ch === null || !isBreak(ch)) {
          if (chars[start] === LF) this.writeLineBreak();
          for (const br of chars.slice(start, end)) {
            if (br === LF) this.writeLineBreak();
            else this.writeLineBreak(br);
          }
          this.writeIndent();
          this.whitespace = false;
          this.indention = false;
          start = end;
        }
      } else if (ch === null || ch === ' ' || isBreak(ch)) {
        const data = chars.slice(start, end).join('');
        this.column += end - start;
        this.write(data);
        start = end;
      }
      if (ch !== null) {
        spaces = ch === ' ';
        breaks = isBreak(ch);
      }
      end += 1;
    }
  }
}

function percentEncode(ch) {
  let out = '';
  const bytes = [];
  const cp = ch.codePointAt(0);
  if (cp < 0x80) {
    bytes.push(cp);
  } else if (cp < 0x800) {
    bytes.push(0xc0 | (cp >> 6), 0x80 | (cp & 0x3f));
  } else if (cp < 0x10000) {
    bytes.push(0xe0 | (cp >> 12), 0x80 | ((cp >> 6) & 0x3f), 0x80 | (cp & 0x3f));
  } else {
    bytes.push(0xf0 | (cp >> 18), 0x80 | ((cp >> 12) & 0x3f),
      0x80 | ((cp >> 6) & 0x3f), 0x80 | (cp & 0x3f));
  }
  for (const b of bytes) out += '%' + hexUpper(b, 2);
  return out;
}

export { ScalarAnalysis };
